# Ported from Kaitet live Server Script "wm_payment" (API) — logic unchanged.
# Farms / projects / company / approver roles now come from Work Management Settings
# (falls back to the original Kaitet defaults) — see upande_work_management/api/config.py.
# REGENERATED by kaitet-work-management/port_app.py — edit the mirror script, not this file.

import json

import frappe

from upande_work_management.api.config import get_config


@frappe.whitelist()
def wm_payment(**kwargs):
    _cfg = get_config()
    FARM_PROJECT = _cfg["farm_project"]
    DEFAULT_COMPANY = _cfg["default_company"]
    FARMS = _cfg["farms"]
    BLOCK_EXCLUDE = _cfg["block_exclude"]
    FARM_APPROVER_ROLE = _cfg["farm_approver_role"]

    # ==================================================================
    # SERVER SCRIPT — "WM Payment" (API, api_method=wm_payment)
    # Powers: Planner + Assigner (a_) + Actuals (act_) + Payment (pay_) + dash
    # Multi-block planner (Option A) + fast grouped-query dashboard.
    # ==================================================================

    # Hours model: Mon-Fri = 8h, Sat = 6h, Sun counts as a workday = 8h.
    # (No def/return allowed at module top-level in the sandbox, so hours are computed inline
    #  wherever needed using frappe.utils.getdate(d).weekday(): Mon=0 .. Sun=6.)
    WEEKDAY_HOURS = 8
    SATURDAY_HOURS = 6
    SUNDAY_HOURS = 8

    # WHO THIS SYSTEM PAYS
    # Task work only. Permanent, Contract and Temporary staff are salaried and paid
    # through payroll, so their recorded work must never turn into a payment here.
    # The row's own employment_type column cannot be trusted for this -- every row
    # carries "Task Worker" regardless of the Employee master -- so the test always
    # reads tabEmployee.
    # An employee qualifies if ANY of the three configured lists matches. A blank
    # employment type on a new hire therefore does not quietly make them unpayable.
    TW_FIELDS = [
        ("employment_type", frappe.db.get_single_value("Work Management Settings", "tw_employment_types")),
        ("designation", frappe.db.get_single_value("Work Management Settings", "tw_designations")),
        ("custom_category", frappe.db.get_single_value("Work Management Settings", "tw_categories")),
    ]
    TW_CLAUSES = []
    for tw_col, tw_raw in TW_FIELDS:
        tw_vals = []
        for tw_v in str(tw_raw or "").split(","):
            tw_c = tw_v.strip()
            # values come from Settings and land in SQL, so allow only the shapes a
            # job title can actually take and drop anything else outright
            tw_ok = 1
            for tw_ch in tw_c:
                if not (tw_ch.isalnum() or tw_ch in " -_/&().'"):
                    tw_ok = 0
            if tw_c and tw_ok:
                tw_vals.append("'" + tw_c.replace("'", "''") + "'")
        if tw_vals:
            TW_CLAUSES.append("twe." + tw_col + " IN (" + ", ".join(tw_vals) + ")")
    if not TW_CLAUSES:
        # never leave the gate wide open if Settings is blank or unusable
        TW_CLAUSES = ["twe.employment_type = 'Task Worker'"]
    TW_ONLY = (" AND EXISTS (SELECT 1 FROM `tabEmployee` twe WHERE twe.name = we.employee"
               "             AND (" + " OR ".join(TW_CLAUSES) + "))")

    # WHO MAY SEND WORK TO ACCOUNTS
    # Sending creates the payment record and commits the money, so it is limited to
    # the HR head, accounting and the general manager. Everyone else can review and
    # audit; the buttons are hidden for them and the actions refuse server-side, so
    # hiding the UI is not the only thing standing between a farm clerk and payroll.
    SEND_ROLES = ["HOD HR", "Accounts Manager", "Accounts User", "General Manager", "System Manager"]
    send_role_list = frappe.db.get_all("Has Role", filters={"parent": frappe.session.user}, pluck="role")
    CAN_SEND = 0
    for sr in SEND_ROLES:
        if sr in send_role_list:
            CAN_SEND = 1

    action = frappe.form_dict.get("action") or "meta"
    out = {}

    # ===== PLANNER =====
    if action == "pay_confirmed":
        rows = frappe.db.get_all("Work Management Actuals",
            filters={"workflow_state":"CONFIRMED","paid":0},
            fields=["name","farm","task","block_section","payroll_people","total_payment","entry_date"],
            order_by="farm", limit=500)
        out["actuals"] = rows

    elif action == "pay_submit" and not CAN_SEND:
        out["error"] = ("Only the HR head, accounting or the general manager can send work to "
                        "accounts. You can review and audit, but not create the payment.")

    elif action == "pay_submit":
        # Worker-centric: pay a list of employees. Each becomes ONE payment line summarising
        # their unpaid confirmed earnings; on mark-paid we stamp their individual rows.
        title = frappe.form_dict.get("title")
        workers_raw = frappe.form_dict.get("workers")
        submit_now = frappe.form_dict.get("submit_now")
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        err = None
        emp_list = []
        if workers_raw:
            for e in workers_raw.split(","):
                ev = e.strip()
                if ev and ev not in emp_list:
                    emp_list.append(ev)
        if not emp_list: err = "Select at least one worker to pay"
        if err:
            out["error"] = err
        else:
            d = frappe.new_doc("Work Management Payment")
            d.run_title = title or ("Payment run " + frappe.utils.today())
            d.company = DEFAULT_COMPANY
            d.payroll_date = frappe.utils.today()
            d.prepared_by = frappe.session.user
            # store the window if the fields exist (safe: set_value later per-row anyway)
            try:
                if dfrom:
                    d.period_from = dfrom
                if dto:
                    d.period_to = dto
            except Exception:
                pass
            gt = 0
            cnt = 0
            for emp in emp_list:
                aconds = "we.employee=%s AND ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0"
                aparams = [emp]
                if dfrom:
                    aconds = aconds + " AND we.work_date >= %s"
                    aparams.append(dfrom)
                if dto:
                    aconds = aconds + " AND we.work_date <= %s"
                    aparams.append(dto)
                agg = frappe.db.sql("""
                    SELECT we.employee_name nm, ac.farm farm,
                           COUNT(DISTINCT we.work_date) days,
                           COALESCE(SUM(we.actual_quantity),0) qty,
                           COALESCE(SUM(we.amount),0) owed
                    FROM `tabWork Actuals Employee` we
                    INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                    WHERE """ + aconds + """
                """, tuple(aparams), as_dict=True)
                if not agg or frappe.utils.flt(agg[0].owed) <= 0:
                    continue
                g = agg[0]
                row = d.append("lines", {})
                row.employee = emp
                row.employee_name = g.nm
                row.farm = g.farm
                row.days = g.days
                row.qty = g.qty
                row.paid_workers = 1
                row.amount = frappe.utils.flt(g.owed)
                gt = gt + frappe.utils.flt(g.owed)
                cnt = cnt + 1
            d.amount = gt
            d.total_workers = cnt
            d.total_actuals = cnt
            d.flags.ignore_permissions = True
            d.insert(ignore_permissions=True)
            if submit_now:
                frappe.db.set_value("Work Management Payment", d.name, "workflow_state", "Unpaid", update_modified=False)
                d.workflow_state = "Unpaid"
            out["name"] = d.name
            out["workflow_state"] = d.workflow_state
            out["amount"] = d.amount
            out["total_workers"] = cnt

    elif action == "pay_workers":
        # Worker-centric. Optional: farms (CSV) + date range (filters payable work_days).
        # include_all=1 -> return EVERY confirmed worker in range with a status (Unpaid/Submitted/Paid)
        #                  and the run ref; paid/submitted rows are shown but not payable.
        farms_raw = frappe.form_dict.get("farms")
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        include_all = frappe.form_dict.get("include_all")
        conds = "ac.workflow_state='CONFIRMED' AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0" + TW_ONLY
        if not include_all:
            conds = conds + " AND IFNULL(we.paid,0)=0"
        params = []
        farm_list = []
        if farms_raw:
            for f in farms_raw.split(","):
                fv = f.strip()
                if fv:
                    farm_list.append(fv)
        if farm_list:
            ph = ",".join(["%s"] * len(farm_list))
            conds = conds + " AND ac.farm IN (" + ph + ")"
            for fv in farm_list:
                params.append(fv)
        if dfrom:
            conds = conds + " AND we.work_date >= %s"
            params.append(dfrom)
        if dto:
            conds = conds + " AND we.work_date <= %s"
            params.append(dto)
        rows = frappe.db.sql("""
            SELECT we.employee emp, we.employee_name emp_name, ac.farm farm,
                   COUNT(DISTINCT we.work_date) days,
                   COUNT(DISTINCT ac.task) tasks,
                   MIN(we.work_date) wfrom, MAX(we.work_date) wto,
                   COALESCE(SUM(we.actual_quantity),0) qty,
                   COALESCE(SUM(we.amount),0) owed,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=1 THEN we.amount ELSE 0 END),0) paid_amt,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 THEN we.amount ELSE 0 END),0) unpaid_amt,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 AND IFNULL(we.custom_reviewed,0)=0 THEN we.amount ELSE 0 END),0) unreviewed_amt,
                   COUNT(DISTINCT ac.name) docs,
                   MIN(IFNULL(we.paid,0)) min_paid,
                   MAX(IFNULL(we.paid,0)) max_paid,
                   MAX(we.payment_ref) run_ref
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + conds + """
            GROUP BY we.employee, we.employee_name, ac.farm
            ORDER BY ac.farm, owed DESC
        """, tuple(params), as_dict=True)
        # attendance-conflict flag per worker: day-rows in this window that fall on
        # a marked-Absent day (the headline discrepancy — full detail lives in the
        # review sheet's Discrepancies tab)
        disc_map = {}
        drows = frappe.db.sql("""
            SELECT we.employee emp, COUNT(*) n
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            INNER JOIN `tabAttendance` att ON att.employee = we.employee
                  AND att.attendance_date = we.work_date
                  AND att.docstatus = 1 AND att.status = 'Absent'
            WHERE """ + conds + " AND NOT EXISTS (\n                SELECT 1 FROM `tabAttendance` pp\n                WHERE pp.employee = att.employee AND pp.attendance_date = att.attendance_date\n                  AND pp.docstatus = 1 AND pp.status IN ('Present','Half Day','Work From Home')\n              )" + """
            GROUP BY we.employee
        """, tuple(params), as_dict=True)
        for r in drows:
            disc_map[r.emp] = frappe.utils.cint(r.n)
        # derive status per worker
        for r in rows:
            r["disc_days"] = disc_map.get(r.emp, 0)
            rref = r.get("run_ref")
            runstate = None
            if rref:
                runstate = frappe.db.get_value("Work Management Payment", rref, "workflow_state")
            if r.get("max_paid") == 1 and r.get("min_paid") == 1:
                r["pay_status"] = "Paid"
            elif rref and runstate in ("Unpaid",):
                r["pay_status"] = "Sent to accounts"
            elif rref and runstate == "Paid" and frappe.utils.flt(r.get("unpaid_amt")) <= 0.001:
                r["pay_status"] = "Paid"
            elif r.get("max_paid") == 1 and frappe.utils.flt(r.get("unpaid_amt")) <= 0.001:
                r["pay_status"] = "Paid"
            else:
                r["pay_status"] = "Unpaid"
            r["run_ref"] = rref or None
            r["wfrom"] = str(r.get("wfrom")) if r.get("wfrom") else None
            r["wto"] = str(r.get("wto")) if r.get("wto") else None
            r["payable"] = 1 if r["pay_status"] == "Unpaid" else 0
        out["workers"] = rows
        tot = 0
        for r in rows:
            if r.get("payable"):
                tot = tot + frappe.utils.flt(r.owed)
        out["amount"] = tot
        # ALL farms that have earnings in the same window (unpaid-only for the multi-select summary)
        fconds = "ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0"
        fparams = []
        if dfrom:
            fconds = fconds + " AND we.work_date >= %s"
            fparams.append(dfrom)
        if dto:
            fconds = fconds + " AND we.work_date <= %s"
            fparams.append(dto)
        allfarms = frappe.db.sql("""
            SELECT ac.farm farm, COUNT(DISTINCT we.employee) workers, COALESCE(SUM(we.amount),0) owed
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + fconds + """
            GROUP BY ac.farm ORDER BY ac.farm
        """, tuple(fparams), as_dict=True)
        out["farms"] = allfarms

    elif action == "pay_worker_detail":
        # One worker's completed jobs (per task/plan/day) that are confirmed + unpaid
        emp = frappe.form_dict.get("employee")
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        jconds = "we.employee=%s AND ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1"
        jparams = [emp]
        if dfrom:
            jconds = jconds + " AND we.work_date >= %s"
            jparams.append(dfrom)
        if dto:
            jconds = jconds + " AND we.work_date <= %s"
            jparams.append(dto)
        jobs = frappe.db.sql("""
            SELECT ac.name actuals, ac.farm farm, ac.task task, ac.block_section block,
                   we.work_date wdate, we.actual_quantity qty, we.amount amount,
                   CASE WHEN IFNULL(we.actual_quantity,0) > 0
                        THEN we.amount / we.actual_quantity ELSE ac.rate END rate
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + jconds + """
            ORDER BY we.work_date
        """, tuple(jparams), as_dict=True)
        empinfo = frappe.db.get_value("Employee", emp, ["employee_name","custom_farm"], as_dict=True)
        out["employee"] = emp
        out["employee_name"] = empinfo.employee_name if empinfo else emp
        out["jobs"] = jobs
        tot = 0
        days = {}
        for j in jobs:
            tot = tot + frappe.utils.flt(j.amount)
            days[str(j.wdate)] = 1
        out["total_owed"] = tot
        out["total_days"] = len(days)

    elif action == "pay_pending":
        # The queue can run to thousands. It is paged rather than silently cut off
        # at 200: the true total always comes back, so the tab can never imply the
        # queue is smaller than it is.
        pp_limit = frappe.utils.cint(frappe.form_dict.get("limit") or 200)
        if pp_limit < 1:
            pp_limit = 200
        if pp_limit > 1000:
            pp_limit = 1000
        pp_start = frappe.utils.cint(frappe.form_dict.get("start") or 0)
        pp_week = frappe.form_dict.get("payroll_date")
        # Same filters the Pay workers tab offers, so accounts can narrow the queue
        # the way the person who built it did: farm, worked-date range, and a search
        # over the worker or the reference. Applied server-side, so the totals and
        # the paging stay honest rather than filtering only the page on screen.
        pp_farms = (frappe.form_dict.get("farms") or "").strip()
        pp_from = frappe.form_dict.get("from_date")
        pp_to = frappe.form_dict.get("to_date")
        pp_q = (frappe.form_dict.get("q") or "").strip()
        pp_filters = {"workflow_state": "Unpaid"}
        if pp_week:
            pp_filters["payroll_date"] = pp_week
        pp_cond = "p.workflow_state = 'Unpaid'"
        pp_args = {}
        if pp_week:
            pp_cond = pp_cond + " AND p.payroll_date = %(wk)s"
            pp_args["wk"] = pp_week
        if pp_farms:
            pp_flist = [f.strip() for f in pp_farms.split(",") if f.strip()]
            if pp_flist:
                pp_cond = pp_cond + " AND p.farm IN %(fl)s"
                pp_args["fl"] = tuple(pp_flist)
        if pp_from:
            pp_cond = pp_cond + " AND p.period_to >= %(pf)s"
            pp_args["pf"] = pp_from
        if pp_to:
            pp_cond = pp_cond + " AND p.period_from <= %(pt)s"
            pp_args["pt"] = pp_to
        if pp_q:
            pp_cond = pp_cond + (" AND (p.name LIKE %(q)s OR p.run_title LIKE %(q)s"
                                 " OR EXISTS (SELECT 1 FROM `tabWork Payment Line` wl"
                                 " WHERE wl.parent = p.name AND (wl.employee LIKE %(q)s"
                                 " OR wl.employee_name LIKE %(q)s)))")
            pp_args["q"] = "%" + pp_q + "%"
        pp_agg = frappe.db.sql("""
            SELECT COUNT(*) n, COALESCE(SUM(p.amount),0) a
            FROM `tabWork Management Payment` p WHERE """ + pp_cond, pp_args, as_dict=True)[0]
        out["total"] = frappe.utils.cint(pp_agg.n)
        out["total_amount"] = frappe.utils.flt(pp_agg.a)
        out["filtered"] = 1 if (pp_farms or pp_from or pp_to or pp_q) else 0
        out["queue_total"] = frappe.db.count("Work Management Payment", {"workflow_state": "Unpaid"})
        out["farms"] = frappe.db.sql("""
            SELECT p.farm, COUNT(*) n FROM `tabWork Management Payment` p
            WHERE p.workflow_state = 'Unpaid' AND IFNULL(p.farm,'') != ''
            GROUP BY p.farm ORDER BY p.farm
        """, as_dict=True)
        # every pay week in the queue, so accounts can work a week at a time
        pp_wcond = pp_cond
        if pp_week:
            pp_wcond = pp_wcond.replace(" AND p.payroll_date = %(wk)s", "")
        out["weeks"] = frappe.db.sql("""
            SELECT p.payroll_date, p.period_from, p.period_to, COUNT(*) n,
                   COALESCE(SUM(p.amount),0) amount
            FROM `tabWork Management Payment` p
            WHERE """ + pp_wcond + """
            GROUP BY p.payroll_date, p.period_from, p.period_to
            ORDER BY p.payroll_date DESC
        """, pp_args, as_dict=True)
        pp_args["lim"] = pp_limit
        pp_args["off"] = pp_start
        pend = frappe.db.sql("""
            SELECT p.name, p.run_title, p.total_actuals, p.total_workers, p.amount,
                   p.prepared_by, p.payroll_date, p.period_from, p.period_to, p.farm
            FROM `tabWork Management Payment` p
            WHERE """ + pp_cond + """
            ORDER BY p.payroll_date DESC, p.name ASC
            LIMIT %(lim)s OFFSET %(off)s
        """, pp_args, as_dict=True)
        # one query for the worker names rather than one per payment
        pp_names = [pr.name for pr in pend]
        pp_emp = {}
        if pp_names:
            for ln in frappe.db.sql("""
                SELECT parent, employee, employee_name FROM `tabWork Payment Line`
                WHERE parent IN %(p)s GROUP BY parent, employee, employee_name
            """, {"p": tuple(pp_names)}, as_dict=True):
                if ln.parent not in pp_emp:
                    pp_emp[ln.parent] = ln
        for pr in pend:
            ln = pp_emp.get(pr.name)
            pr["employee"] = ln.employee if ln else None
            pr["employee_name"] = ln.employee_name if ln else None
            pr["period_from"] = str(pr.period_from) if pr.period_from else None
            pr["period_to"] = str(pr.period_to) if pr.period_to else None
            pr["payroll_date"] = str(pr.payroll_date) if pr.payroll_date else None
        out["pending"] = pend
        out["start"] = pp_start
        out["limit"] = pp_limit
        out["returned"] = len(pend)
        out["has_more"] = 1 if (pp_start + len(pend)) < out["total"] else 0

    elif action == "pay_mark_paid":
        nm = frappe.form_dict.get("name")
        cur = frappe.db.get_value("Work Management Payment", nm,
            ["workflow_state","period_from","period_to"], as_dict=True)
        if not cur or cur.workflow_state != "Unpaid":
            out["error"] = "Not awaiting accounts (state: " + str(cur.workflow_state if cur else "not found") + ")"
        else:
            # finalise via direct writes (bypass workflow engine + doctype gate)
            frappe.db.set_value("Work Management Payment", nm, "workflow_state", "Paid", update_modified=False)
            frappe.db.set_value("Work Management Payment", nm, "docstatus", 1, update_modified=False)
            frappe.db.set_value("Work Management Payment", nm, "accounts_approved_by", frappe.session.user, update_modified=False)
            frappe.db.set_value("Work Management Payment", nm, "accounts_approval_date", frappe.utils.today(), update_modified=False)
            # stamp each paid worker's confirmed-unpaid rows as paid (row-level)
            touched_parents = {}
            pfrom = cur.period_from
            pto = cur.period_to
            # resolve the child doctype of the 'lines' table field (name varies)
            line_dt = None
            pmeta = frappe.get_meta("Work Management Payment")
            for f in pmeta.fields:
                if f.fieldtype == "Table" and f.fieldname == "lines":
                    line_dt = f.options
            lines = []
            if line_dt:
                lines = frappe.db.get_all(line_dt, filters={"parent": nm}, fields=["employee"])
            for ln in lines:
                emp = ln.employee
                if not emp:
                    continue
                rconds = "we.employee=%s AND ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1"
                rparams = [emp]
                if pfrom:
                    rconds = rconds + " AND we.work_date >= %s"
                    rparams.append(pfrom)
                if pto:
                    rconds = rconds + " AND we.work_date <= %s"
                    rparams.append(pto)
                payrows = frappe.db.sql("""
                    SELECT we.name rowname, we.parent parent
                    FROM `tabWork Actuals Employee` we
                    INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                    WHERE """ + rconds + """
                """, tuple(rparams), as_dict=True)
                for pr in payrows:
                    frappe.db.set_value("Work Actuals Employee", pr.rowname, "paid", 1, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", pr.rowname, "payment_ref", nm, update_modified=False)
                    touched_parents[pr.parent] = 1
            # flip parent Actuals paid=1 only when ALL its payable rows are now paid
            for parent in touched_parents:
                unpaid = frappe.db.sql("""
                    SELECT COUNT(*) c FROM `tabWork Actuals Employee`
                    WHERE parent=%s AND IFNULL(count_in_payroll,0)=1 AND amount>0 AND IFNULL(paid,0)=0
                """, (parent,), as_dict=True)
                if unpaid and unpaid[0].c == 0:
                    frappe.db.set_value("Work Management Actuals", parent, "paid", 1, update_modified=False)
                    frappe.db.set_value("Work Management Actuals", parent, "payment_ref", nm, update_modified=False)
            frappe.db.commit()
            out["name"] = nm; out["workflow_state"] = "Paid"

    elif action == "pay_my":
        out["runs"] = frappe.db.get_all("Work Management Payment",
            filters={"prepared_by":frappe.session.user},
            fields=["name","run_title","total_actuals","total_workers","amount","workflow_state","payroll_date"],
            order_by="creation desc", limit=200)

    elif action == "pay_roles":
        rl = frappe.db.get_all("Has Role", filters={"parent": frappe.session.user}, pluck="role")
        is_acc = ("Accounts User" in rl) or ("Accounts Manager" in rl) or ("System Manager" in rl)
        out["user"] = frappe.session.user
        out["is_accounts"] = 1 if is_acc else 0
        out["can_send"] = CAN_SEND
        # the page picks pay weeks, not free dates, so it needs the configured
        # week boundary
        r_names = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
        r_start = frappe.db.get_single_value("Work Management Settings", "pay_week_starts_on") or "Sunday"
        r_end = frappe.db.get_single_value("Work Management Settings", "pay_week_ends_on") or "Saturday"
        r_pay = frappe.db.get_single_value("Work Management Settings", "pay_day") or r_end
        r_si = r_names.index(r_start) if r_start in r_names else 6
        r_ei = r_names.index(r_end) if r_end in r_names else 5
        out["week_starts_on"] = r_start
        out["week_ends_on"] = r_end
        out["pay_day"] = r_pay
        out["week_days"] = ((r_ei - r_si) % 7) + 1

    elif action == "pay_audit":
        # Reconcile CONFIRMED actuals against assigner + payment, per task/block, for the range.
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        farms_raw = frappe.form_dict.get("farms")
        farm_list = []
        if farms_raw:
            for f in farms_raw.split(","):
                fv = f.strip()
                if fv:
                    farm_list.append(fv)
        conds = "ac.workflow_state='CONFIRMED'"
        params = []
        if dfrom:
            conds = conds + " AND we.work_date >= %s"
            params.append(dfrom)
        if dto:
            conds = conds + " AND we.work_date <= %s"
            params.append(dto)
        if farm_list:
            ph = ",".join(["%s"] * len(farm_list))
            conds = conds + " AND ac.farm IN (" + ph + ")"
            for fv in farm_list:
                params.append(fv)
        # ---- SUMMARY: one row per actuals doc (task/block/assignment) ----
        summ = frappe.db.sql("""
            SELECT ac.name actuals, ac.farm farm, ac.task task, ac.block_section block,
                   ac.assignment assignment, ac.entry_date entry_date, ac.entered_by entered_by,
                   COUNT(DISTINCT we.employee) workers,
                   COUNT(*) worker_days,
                   COALESCE(SUM(we.actual_quantity),0) actual_qty,
                   COALESCE(SUM(we.amount),0) total_pay,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=1 THEN we.amount ELSE 0 END),0) paid_pay,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 THEN we.amount ELSE 0 END),0) unpaid_pay,
                   MAX(we.payment_ref) run_refs
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + conds + """
            GROUP BY ac.name, ac.farm, ac.task, ac.block_section, ac.assignment, ac.entry_date, ac.entered_by
            ORDER BY ac.farm, total_pay DESC
        """, tuple(params), as_dict=True)
        sumrows = []
        t_tasks = 0
        t_qty = 0
        t_total = 0
        t_paid = 0
        t_unpaid = 0
        t_wdays = 0
        for s in summ:
            # enrich with assigner planned/assigned + plan link
            planned = 0
            assigned = 0
            variance = 0
            planner = None
            pfrom = None
            pto = None
            if s.assignment:
                ai = frappe.db.get_value("Work Management Assigner", s.assignment,
                    ["planned_people","assigned_count","variance","planner_request"], as_dict=True)
                if ai:
                    planned = frappe.utils.cint(ai.planned_people)
                    assigned = frappe.utils.cint(ai.assigned_count)
                    variance = frappe.utils.cint(ai.variance)
                    planner = ai.planner_request
            if planner:
                pd = frappe.db.get_value("Work Management Planner", planner, ["from_date","to_date"], as_dict=True)
                if pd:
                    pfrom = str(pd.from_date) if pd.from_date else None
                    pto = str(pd.to_date) if pd.to_date else None
            # pay status for the doc
            tot = frappe.utils.flt(s.total_pay)
            paid = frappe.utils.flt(s.paid_pay)
            unpaid = frappe.utils.flt(s.unpaid_pay)
            run_state = None
            if s.run_refs:
                run_state = frappe.db.get_value("Work Management Payment", s.run_refs, "workflow_state")
            if tot > 0 and paid >= tot - 0.001:
                pstat = "Paid"
            elif paid > 0:
                pstat = "Part paid"
            elif s.run_refs and run_state == "Unpaid":
                pstat = "In run (awaiting accounts)"
            else:
                pstat = "Unpaid"
            sumrows.append({
                "actuals": s.actuals, "farm": s.farm, "task": s.task, "block": s.block,
                "assignment": s.assignment, "planner_request": planner, "from_date": pfrom, "to_date": pto,
                "planned_people": planned, "assigned_count": assigned, "variance": variance,
                "actual_qty": frappe.utils.flt(s.actual_qty), "workers": frappe.utils.cint(s.workers),
                "worker_days": frappe.utils.cint(s.worker_days),
                "total_pay": tot, "paid_pay": paid, "unpaid_pay": unpaid,
                "pay_status": pstat, "run_refs": s.run_refs, "entered_by": s.entered_by,
                "entry_date": str(s.entry_date) if s.entry_date else None
            })
            t_tasks = t_tasks + 1
            t_qty = t_qty + frappe.utils.flt(s.actual_qty)
            t_total = t_total + tot
            t_paid = t_paid + paid
            t_unpaid = t_unpaid + unpaid
            t_wdays = t_wdays + frappe.utils.cint(s.worker_days)
        out["summary"] = sumrows
        # ---- DETAIL: one row per worker per day ----
        det = frappe.db.sql("""
            SELECT ac.farm farm, ac.task task, ac.block_section block, ac.assignment assignment,
                   we.employee emp, we.employee_name emp_name, we.employment_type emp_type,
                   we.work_date wdate, we.actual_quantity qty, we.amount amount,
                   IFNULL(we.count_in_payroll,0) in_payroll,
                   IFNULL(we.paid,0) paid, IFNULL(we.custom_reviewed,0) reviewed, we.payment_ref run_ref
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + conds + """
            ORDER BY ac.farm, ac.task, we.employee_name, we.work_date
        """, tuple(params), as_dict=True)
        detrows = []
        for d in det:
            pstat = "Paid" if frappe.utils.cint(d.paid) == 1 else "Unpaid"
            detrows.append({
                "farm": d.farm, "task": d.task, "block": d.block, "assignment": d.assignment,
                "emp": d.emp, "emp_name": d.emp_name, "emp_type": d.emp_type,
                "wdate": str(d.wdate) if d.wdate else None,
                "qty": frappe.utils.flt(d.qty), "amount": frappe.utils.flt(d.amount),
                "in_payroll": frappe.utils.cint(d.in_payroll), "pay_status": pstat, "run_ref": d.run_ref,
                "reviewed": frappe.utils.cint(d.reviewed)
            })
        out["detail"] = detrows
        out["totals"] = {"tasks": t_tasks, "qty": t_qty, "total_pay": t_total,
                         "paid": t_paid, "unpaid": t_unpaid, "worker_days": t_wdays}

    elif action == "pay_insights":
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        farm = frappe.form_dict.get("farm")
        conds = "ac.workflow_state='CONFIRMED'"
        params = []
        if dfrom:
            conds = conds + " AND we.work_date >= %s"
            params.append(dfrom)
        if dto:
            conds = conds + " AND we.work_date <= %s"
            params.append(dto)
        if farm:
            conds = conds + " AND ac.farm = %s"
            params.append(farm)
        # KPIs
        kp = frappe.db.sql("""
            SELECT COUNT(DISTINCT we.employee) active_workers,
                   COUNT(*) mandays,
                   COALESCE(SUM(we.amount),0) earned,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=1 THEN we.amount ELSE 0 END),0) paid_amt,
                   COUNT(DISTINCT CASE WHEN IFNULL(we.paid,0)=1 THEN we.employee END) paid_workers,
                   COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 THEN we.amount ELSE 0 END),0) unpaid_amt,
                   COUNT(DISTINCT CASE WHEN IFNULL(we.paid,0)=0 THEN we.employee END) unpaid_workers
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + conds + """
        """, tuple(params), as_dict=True)
        k = kp[0] if kp else {}
        out["kpi"] = {
            "active_workers": frappe.utils.cint(k.active_workers) if kp else 0,
            "mandays": frappe.utils.cint(k.mandays) if kp else 0,
            "earned": frappe.utils.flt(k.earned) if kp else 0,
            "paid_amt": frappe.utils.flt(k.paid_amt) if kp else 0,
            "paid_workers": frappe.utils.cint(k.paid_workers) if kp else 0,
            "unpaid_amt": frappe.utils.flt(k.unpaid_amt) if kp else 0,
            "unpaid_workers": frappe.utils.cint(k.unpaid_workers) if kp else 0
        }
        # assigned workers (live assignments in window/farm)
        aconds = "a.workflow_state IN ('Pending Farm Manager','Pending HR Head','Pending GM','Assigned')"
        aparams = []
        if farm:
            aconds = aconds + " AND a.farm = %s"
            aparams.append(farm)
        asg = frappe.db.sql("""
            SELECT COUNT(DISTINCT we.employee) c
            FROM `tabWork Assignment Employee` we
            INNER JOIN `tabWork Management Assigner` a ON we.parent = a.name
            WHERE """ + aconds + """ AND IFNULL(we.status,'Active')='Active'
        """, tuple(aparams), as_dict=True)
        out["assigned_workers"] = frappe.utils.cint(asg[0].c) if asg else 0
        # workforce pool: active Task Workers -> available = pool - assigned
        pconds = "status='Active' AND employment_type='Task Worker'"
        pparams = []
        if farm:
            pconds = pconds + " AND custom_farm = %s"
            pparams.append(farm)
        pool = frappe.db.sql("""
            SELECT name emp, employee_name nm, custom_farm farm, designation
            FROM `tabEmployee` WHERE """ + pconds + """
            ORDER BY employee_name LIMIT 3000
        """, tuple(pparams), as_dict=True)
        out["pool_count"] = len(pool)
        arows = frappe.db.sql("""
            SELECT we.employee emp, we.employee_name nm, a.farm farm, a.task task,
                   a.name assignment, a.from_date fdate, a.to_date tdate, a.workflow_state state
            FROM `tabWork Assignment Employee` we
            INNER JOIN `tabWork Management Assigner` a ON we.parent = a.name
            WHERE """ + aconds + """ AND IFNULL(we.status,'Active')='Active'
            ORDER BY a.from_date DESC LIMIT 5000
        """, tuple(aparams), as_dict=True)
        aset = {}
        amap = {}
        for r in arows:
            aset[r.emp] = 1
            g = amap.get(r.emp)
            if not g:
                g = {"emp": r.emp, "nm": r.nm, "farm": r.farm, "assignments": 0, "tasks": {}, "latest_from": None, "latest_to": None}
                amap[r.emp] = g
            g["assignments"] = g["assignments"] + 1
            if r.task:
                g["tasks"][r.task] = 1
            if not g["latest_from"]:
                g["latest_from"] = str(r.fdate) if r.fdate else None
                g["latest_to"] = str(r.tdate) if r.tdate else None
        alist = []
        for k2 in amap:
            g = amap[k2]
            tl = []
            for tk in g["tasks"]:
                tl.append(tk)
            tl = sorted(tl)
            g["task_list"] = ", ".join(tl)
            g["task_count"] = len(tl)
            del g["tasks"]
            alist.append(g)
        alist = sorted(alist, key=lambda x: x["assignments"], reverse=True)
        out["assigned_list"] = alist
        avail = []
        for p in pool:
            if not aset.get(p.emp):
                avail.append({"emp": p.emp, "nm": p.nm, "farm": p.farm, "designation": p.designation})
        out["available_list"] = avail
        # unpaid list (worker-level, biggest first)
        unp = frappe.db.sql("""
            SELECT we.employee emp, we.employee_name nm, ac.farm farm,
                   COUNT(DISTINCT we.work_date) days, COALESCE(SUM(we.amount),0) owed,
                   MIN(we.work_date) oldest, MAX(we.work_date) newest
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + conds + """ AND IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0
            GROUP BY we.employee, we.employee_name, ac.farm
            ORDER BY owed DESC LIMIT 500
        """, tuple(params), as_dict=True)
        ulist = []
        for u in unp:
            ulist.append({"emp": u.emp, "nm": u.nm, "farm": u.farm,
                "days": frappe.utils.cint(u.days), "owed": frappe.utils.flt(u.owed),
                "oldest": str(u.oldest) if u.oldest else None, "newest": str(u.newest) if u.newest else None})
        out["unpaid_list"] = ulist
        # task costs (per task per farm)
        tc = frappe.db.sql("""
            SELECT ac.task label, ac.farm farm,
                   COALESCE(SUM(we.amount),0) pay, COALESCE(SUM(we.actual_quantity),0) qty,
                   COUNT(DISTINCT we.employee) workers, COUNT(*) mandays
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + conds + """
            GROUP BY ac.task, ac.farm ORDER BY pay DESC LIMIT 500
        """, tuple(params), as_dict=True)
        tclist = []
        for r in tc:
            tclist.append({"label": r.label, "farm": r.farm, "pay": frappe.utils.flt(r.pay),
                "qty": frappe.utils.flt(r.qty), "workers": frappe.utils.cint(r.workers),
                "mandays": frappe.utils.cint(r.mandays)})
        out["task_costs"] = tclist
        # top earners
        top = frappe.db.sql("""
            SELECT we.employee emp, we.employee_name nm, ac.farm farm,
                   COUNT(DISTINCT we.work_date) days, COALESCE(SUM(we.actual_quantity),0) qty,
                   COALESCE(SUM(we.amount),0) pay
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + conds + """
            GROUP BY we.employee, we.employee_name, ac.farm
            ORDER BY pay DESC LIMIT 50
        """, tuple(params), as_dict=True)
        toplist = []
        for r in top:
            toplist.append({"emp": r.emp, "nm": r.nm, "farm": r.farm,
                "days": frappe.utils.cint(r.days), "qty": frappe.utils.flt(r.qty), "pay": frappe.utils.flt(r.pay)})
        out["top_workers"] = toplist
        # idle: assigned but no confirmed work in window
        idle = frappe.db.sql("""
            SELECT we.employee emp, we.employee_name nm, a.farm farm, COUNT(DISTINCT a.name) assignments
            FROM `tabWork Assignment Employee` we
            INNER JOIN `tabWork Management Assigner` a ON we.parent = a.name
            WHERE """ + aconds + """ AND IFNULL(we.status,'Active')='Active'
              AND we.employee NOT IN (
                SELECT DISTINCT we2.employee
                FROM `tabWork Actuals Employee` we2
                INNER JOIN `tabWork Management Actuals` ac2 ON we2.parent = ac2.name
                WHERE ac2.workflow_state='CONFIRMED'""" + (" AND we2.work_date >= %s" if dfrom else "") + (" AND we2.work_date <= %s" if dto else "") + """
              )
            GROUP BY we.employee, we.employee_name, a.farm
            ORDER BY assignments DESC LIMIT 500
        """, tuple(aparams + ([dfrom] if dfrom else []) + ([dto] if dto else [])), as_dict=True)
        ilist = []
        for r in idle:
            ilist.append({"emp": r.emp, "nm": r.nm, "farm": r.farm, "assignments": frappe.utils.cint(r.assignments)})
        out["idle_list"] = ilist
        # farms list for the dropdown
        allf = frappe.db.sql("""SELECT DISTINCT farm FROM `tabWork Management Actuals`
            WHERE farm IS NOT NULL ORDER BY farm""", as_dict=True)
        out["farms"] = [f.farm for f in allf]
        out["window"] = {"farm": farm or None, "from": dfrom or None, "to": dto or None}

    elif action == "pay_worker_history":
        # In-depth overview of ONE worker: every confirmed job (paid or not),
        # grouped per task/actuals doc with plan period, plus the raw daily log,
        # payment runs and headline KPIs. Used by the Audit worker deep-dive.
        emp = frappe.form_dict.get("employee")
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        if not emp:
            out["error"] = "employee is required"
        else:
            hconds = "we.employee=%s AND ac.workflow_state='CONFIRMED'"
            hparams = [emp]
            if dfrom:
                hconds = hconds + " AND we.work_date >= %s"
                hparams.append(dfrom)
            if dto:
                hconds = hconds + " AND we.work_date <= %s"
                hparams.append(dto)
            einfo = frappe.db.get_value("Employee", emp,
                ["employee_name", "custom_farm", "designation", "employment_type", "status", "date_of_joining"],
                as_dict=True)
            out["info"] = {
                "employee": emp,
                "employee_name": (einfo.employee_name if einfo else None) or emp,
                "farm": einfo.custom_farm if einfo else None,
                "designation": einfo.designation if einfo else None,
                "employment_type": einfo.employment_type if einfo else None,
                "status": einfo.status if einfo else None,
                "date_of_joining": str(einfo.date_of_joining) if einfo and einfo.date_of_joining else None,
            }
            # KPIs across the window
            kp = frappe.db.sql("""
                SELECT COUNT(*) mandays,
                       COUNT(DISTINCT we.work_date) days,
                       COUNT(DISTINCT ac.task) tasks,
                       COUNT(DISTINCT ac.name) docs,
                       COALESCE(SUM(we.actual_quantity),0) qty,
                       COALESCE(SUM(we.amount),0) earned,
                       COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=1 THEN we.amount ELSE 0 END),0) paid_amt,
                       COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 THEN we.amount ELSE 0 END),0) unpaid_amt,
                       COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 AND IFNULL(we.custom_reviewed,0)=0 THEN we.amount ELSE 0 END),0) unreviewed_amt,
                       MIN(we.work_date) first_day, MAX(we.work_date) last_day
                FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                WHERE """ + hconds + """
            """, tuple(hparams), as_dict=True)
            k = kp[0] if kp else None
            days = frappe.utils.cint(k.days) if k else 0
            earned = frappe.utils.flt(k.earned) if k else 0
            out["kpi"] = {
                "mandays": frappe.utils.cint(k.mandays) if k else 0,
                "days": days,
                "tasks": frappe.utils.cint(k.tasks) if k else 0,
                "docs": frappe.utils.cint(k.docs) if k else 0,
                "qty": frappe.utils.flt(k.qty) if k else 0,
                "earned": earned,
                "paid_amt": frappe.utils.flt(k.paid_amt) if k else 0,
                "unpaid_amt": frappe.utils.flt(k.unpaid_amt) if k else 0,
                "unreviewed_amt": frappe.utils.flt(k.unreviewed_amt) if k else 0,
                "avg_per_day": (earned / days) if days else 0,
                "first_day": str(k.first_day) if k and k.first_day else None,
                "last_day": str(k.last_day) if k and k.last_day else None,
            }
            # per actuals doc first, then merged per TASK (many docs are single-day,
            # so grouping by task is what reads naturally: one card per task with
            # its full worked period and every approver involved)
            grp = frappe.db.sql("""
                SELECT ac.name actuals, ac.farm farm, ac.task task, ac.block_section block,
                       ac.assignment assignment, ac.rate doc_rate,
                       ac.entered_by entered_by, ac.hr_approved_by hr_approved_by, ac.gm_approved_by gm_approved_by,
                       MIN(we.work_date) wfrom, MAX(we.work_date) wto,
                       COUNT(DISTINCT we.work_date) days,
                       COALESCE(SUM(we.actual_quantity),0) qty,
                       COALESCE(SUM(we.amount),0) amount,
                       COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=1 THEN we.amount ELSE 0 END),0) paid_amt,
                       COALESCE(SUM(CASE WHEN IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 THEN we.amount ELSE 0 END),0) unpaid_amt,
                       MAX(we.payment_ref) run_ref
                FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                WHERE """ + hconds + """
                GROUP BY ac.name, ac.farm, ac.task, ac.block_section, ac.assignment, ac.rate,
                         ac.entered_by, ac.hr_approved_by, ac.gm_approved_by
                ORDER BY MIN(we.work_date) DESC
            """, tuple(hparams), as_dict=True)
            asg_cache = {}
            std_cache = {}
            tmap = {}
            torder = []
            for g in grp:
                ai = None
                if g.assignment:
                    ai = asg_cache.get(g.assignment)
                    if ai is None:
                        ai = frappe.db.get_value("Work Management Assigner", g.assignment,
                            ["planner_request", "from_date", "to_date", "assigned_by", "approved_by"], as_dict=True)
                        asg_cache[g.assignment] = ai
                key = (g.task or "") + "|" + (g.block or "") + "|" + (g.farm or "")
                t = tmap.get(key)
                if not t:
                    t = {"task": g.task, "block": g.block, "farm": g.farm,
                         "plan_from": None, "plan_to": None, "work_from": None, "work_to": None,
                         "days": 0, "qty": 0, "amount": 0, "paid_amt": 0, "unpaid_amt": 0,
                         "docs": [], "assignments": {}, "runs": {}, "planners": {},
                         "assigned_by": {}, "fm_approved_by": {}, "entered_by": {},
                         "hr_approved_by": {}, "gm_approved_by": {}, "rate_num": 0,
                         "standard": None}
                    tmap[key] = t
                    torder.append(key)
                # the plan's work standard, e.g. "5 Ha/day" (task_kpi verbatim, else
                # daily_target + uom). Shown as the Standard column in review sheets.
                if ai and ai.planner_request and not t["standard"]:
                    std = std_cache.get(ai.planner_request)
                    if std is None:
                        pstd = frappe.db.get_value("Work Management Planner", ai.planner_request,
                            ["task_kpi", "daily_target", "uom"], as_dict=True)
                        std = ""
                        if pstd:
                            if pstd.task_kpi:
                                std = str(pstd.task_kpi)
                            elif frappe.utils.flt(pstd.daily_target) > 0:
                                std = str(frappe.utils.flt(pstd.daily_target)).rstrip("0").rstrip(".") + " " + (pstd.uom or "") + "/day"
                        std_cache[ai.planner_request] = std
                    if std:
                        t["standard"] = std
                t["docs"].append(g.actuals)
                if g.assignment:
                    t["assignments"][g.assignment] = 1
                if g.run_ref:
                    t["runs"][g.run_ref] = 1
                if ai:
                    if ai.planner_request:
                        t["planners"][ai.planner_request] = 1
                    pf = str(ai.from_date) if ai.from_date else None
                    pt = str(ai.to_date) if ai.to_date else None
                    if pf and (not t["plan_from"] or pf < t["plan_from"]):
                        t["plan_from"] = pf
                    if pt and (not t["plan_to"] or pt > t["plan_to"]):
                        t["plan_to"] = pt
                    if ai.assigned_by:
                        t["assigned_by"][ai.assigned_by] = 1
                    if ai.approved_by:
                        t["fm_approved_by"][ai.approved_by] = 1
                for fld in ("entered_by", "hr_approved_by", "gm_approved_by"):
                    v = g.get(fld)
                    if v:
                        t[fld][v] = 1
                wf = str(g.wfrom) if g.wfrom else None
                wt = str(g.wto) if g.wto else None
                if wf and (not t["work_from"] or wf < t["work_from"]):
                    t["work_from"] = wf
                if wt and (not t["work_to"] or wt > t["work_to"]):
                    t["work_to"] = wt
                t["days"] = t["days"] + frappe.utils.cint(g.days)
                t["qty"] = t["qty"] + frappe.utils.flt(g.qty)
                t["amount"] = t["amount"] + frappe.utils.flt(g.amount)
                t["paid_amt"] = t["paid_amt"] + frappe.utils.flt(g.paid_amt)
                t["unpaid_amt"] = t["unpaid_amt"] + frappe.utils.flt(g.unpaid_amt)
            tasks = []
            for key in torder:
                t = tmap[key]
                amt = t["amount"]
                if amt > 0 and t["paid_amt"] >= amt - 0.001:
                    pstat = "Paid"
                elif t["paid_amt"] > 0:
                    pstat = "Part paid"
                else:
                    pstat = "Unpaid"
                tasks.append({
                    "task": t["task"], "block": t["block"], "farm": t["farm"],
                    "plan_from": t["plan_from"], "plan_to": t["plan_to"],
                    "work_from": t["work_from"], "work_to": t["work_to"],
                    "days": t["days"], "qty": t["qty"],
                    "rate": (amt / t["qty"]) if t["qty"] else 0,
                    "amount": amt, "paid_amt": t["paid_amt"], "unpaid_amt": t["unpaid_amt"],
                    "pay_status": pstat,
                    "standard": t["standard"],
                    "doc_count": len(t["docs"]),
                    "assignments": sorted(t["assignments"].keys()),
                    "planners": sorted(t["planners"].keys()),
                    "runs": sorted(t["runs"].keys()),
                    "assigned_by": sorted(t["assigned_by"].keys()),
                    "fm_approved_by": sorted(t["fm_approved_by"].keys()),
                    "entered_by": sorted(t["entered_by"].keys()),
                    "hr_approved_by": sorted(t["hr_approved_by"].keys()),
                    "gm_approved_by": sorted(t["gm_approved_by"].keys()),
                })
            tasks = sorted(tasks, key=lambda x: x["work_to"] or "", reverse=True)
            out["tasks"] = tasks
            # raw daily log
            dl = frappe.db.sql("""
                SELECT ac.name actuals, we.name rowname, we.work_date wdate, ac.task task, ac.block_section block, ac.farm farm,
                       we.actual_quantity qty, we.amount amount, ac.rate doc_rate,
                       IFNULL(we.paid,0) paid, IFNULL(we.count_in_payroll,0) in_payroll,
                       IFNULL(we.custom_reviewed,0) reviewed, we.payment_ref run_ref
                FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                WHERE """ + hconds + """
                ORDER BY we.work_date ASC
            """, tuple(hparams), as_dict=True)
            # presence evidence per worked day: first scan time + attendance status
            # (P = scan/Present, A = marked Absent yet work recorded, ? = no record)
            ev_scan = {}
            ev_att = {}
            ddates = tuple(set([str(r.wdate) for r in dl if r.wdate]))
            if ddates:
                for r2 in frappe.db.sql("""
                    SELECT DATE(`time`) d, MIN(`time`) t FROM `tabEmployee Checkin`
                    WHERE employee = %s AND DATE(`time`) IN %s GROUP BY DATE(`time`)
                """, (emp, ddates), as_dict=True):
                    ev_scan[str(r2.d)] = str(r2.t)[11:16]
                for r2 in frappe.db.sql("""
                    SELECT attendance_date d, status FROM `tabAttendance`
                    WHERE docstatus = 1 AND employee = %s AND attendance_date IN %s
                """, (emp, ddates), as_dict=True):
                    dk2 = str(r2.d)
                    if r2.status in ('Present', 'Half Day', 'Work From Home'):
                        ev_att[dk2] = r2.status
                    elif ev_att.get(dk2) not in ('Present', 'Half Day', 'Work From Home'):
                        ev_att[dk2] = r2.status
            ev_leave = {}
            ev_off = {}
            if ddates:
                dmin2 = min(ddates)
                dmax2 = max(ddates)
                for r2 in frappe.db.sql("""
                    SELECT leave_type, from_date, to_date FROM `tabLeave Application`
                    WHERE docstatus < 2 AND (status='Approved' OR docstatus=1)
                      AND employee = %s AND from_date <= %s AND to_date >= %s
                """, (emp, dmax2, dmin2), as_dict=True):
                    for dd in ddates:
                        if str(r2.from_date) <= dd <= str(r2.to_date):
                            ev_leave[dd] = r2.leave_type or "leave"
                hl2 = frappe.db.get_value("Employee", emp, "holiday_list")
                if hl2:
                    for r2 in frappe.db.sql("""
                        SELECT holiday_date FROM `tabHoliday`
                        WHERE parent = %s AND holiday_date IN %s
                    """, (hl2, ddates), as_dict=True):
                        ev_off[str(r2.holiday_date)] = 1
            daily = []
            for r in dl:
                qty = frappe.utils.flt(r.qty)
                amt = frappe.utils.flt(r.amount)
                wd = str(r.wdate) if r.wdate else None
                daily.append({
                    "actuals": r.actuals,
                    "rowname": r.rowname,
                    "doc_rate": frappe.utils.flt(r.doc_rate),
                    "editable": 1 if (not frappe.utils.cint(r.paid)) and frappe.utils.cint(r.in_payroll) else 0,
                    "wdate": wd,
                    "task": r.task, "block": r.block, "farm": r.farm,
                    "qty": qty, "amount": amt, "rate": (amt / qty) if qty else 0,
                    "paid": frappe.utils.cint(r.paid), "in_payroll": frappe.utils.cint(r.in_payroll),
                    "reviewed": frappe.utils.cint(r.reviewed), "run_ref": r.run_ref,
                    "scan_in": ev_scan.get(wd) if wd else None,
                    "att_status": ev_att.get(wd) if wd else None,
                    "day_leave": ev_leave.get(wd) if wd else None,
                    "day_off": ev_off.get(wd, 0) if wd else 0,
                })
            out["daily"] = daily
            # payment runs that include this worker
            runs = frappe.db.sql("""
                SELECT p.name run, p.run_title title, p.payroll_date rdate, p.workflow_state state,
                       l.amount amount, l.days days, l.qty qty
                FROM `tabWork Payment Line` l
                INNER JOIN `tabWork Management Payment` p ON l.parent = p.name
                WHERE l.employee = %s
                ORDER BY p.payroll_date DESC LIMIT 100
            """, (emp,), as_dict=True)
            runlist = []
            for r in runs:
                runlist.append({
                    "run": r.run, "title": r.title, "date": str(r.rdate) if r.rdate else None,
                    "state": r.state, "amount": frappe.utils.flt(r.amount),
                    "days": frappe.utils.cint(r.days), "qty": frappe.utils.flt(r.qty),
                })
            out["runs"] = runlist

    elif action == "pay_run_withdraw":
        # Return a pending payment to Unpaid: clear the reference and review stamps
        # on its rows and delete the draft payment doc — the worker redoes
        # review → send from the start.
        nm = frappe.form_dict.get("name")
        cur = frappe.db.get_value("Work Management Payment", nm, "workflow_state")
        if not cur:
            out["error"] = "Payment reference not found"
        elif cur != "Unpaid":
            out["error"] = "Only payments awaiting accounts can be returned (state: " + str(cur) + ")"
        elif frappe.db.sql("""
            SELECT sd.parent FROM `tabSalary Detail` sd
            INNER JOIN `tabAdditional Salary` a ON a.name = sd.additional_salary
            WHERE a.ref_doctype = 'Work Management Payment' AND a.ref_docname = %(n)s LIMIT 1
        """, {"n": nm}, as_dict=True):
            # payroll has already consumed this payment; withdrawing would delete
            # the document a Salary Slip is pointing at
            out["error"] = ("Cannot withdraw: a Salary Slip has already paid this through payroll. "
                            "Reverse it in payroll first.")
        else:
            # cancel the payment's Additional Salary before the document goes --
            # nothing has consumed it, so the payroll record must not outlive it
            for asr in frappe.db.sql("""
                SELECT name FROM `tabAdditional Salary`
                WHERE ref_doctype = 'Work Management Payment' AND ref_docname = %(n)s
                  AND docstatus = 1
            """, {"n": nm}, as_dict=True):
                adoc = frappe.get_doc("Additional Salary", asr.name)
                adoc.flags.ignore_permissions = True
                adoc.cancel()
            rows = frappe.db.get_all("Work Actuals Employee",
                filters={"payment_ref": nm, "paid": 0}, pluck="name")
            for rn in rows:
                frappe.db.set_value("Work Actuals Employee", rn, "payment_ref", None, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", rn, "custom_reviewed", 0, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", rn, "custom_reviewed_by", None, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", rn, "custom_reviewed_at", None, update_modified=False)
            wname = frappe.db.get_value("Work Management Payment", nm, "run_title")
            frappe.delete_doc("Work Management Payment", nm, ignore_permissions=True, force=True)
            frappe.db.commit()
            out["name"] = nm
            out["rows_reset"] = len(rows)
            out["run_title"] = wname

    elif action == "pay_worker_edit_day":
        # Audit-stage correction: change the quantity recorded for one worker-day.
        # Pay recomputes at that row's rate, parent totals are re-summed, and the
        # row's review stamp resets so it must be re-reviewed before payment.
        emp = frappe.form_dict.get("employee")
        rowname = frappe.form_dict.get("rowname")
        new_qty = frappe.utils.flt(frappe.form_dict.get("qty"))
        if not emp or not rowname:
            out["error"] = "employee and rowname are required"
        elif new_qty < 0:
            out["error"] = "Quantity cannot be negative"
        else:
            row = frappe.db.get_value("Work Actuals Employee", rowname,
                ["name", "parent", "employee", "employee_name", "work_date",
                 "actual_quantity", "amount", "paid", "count_in_payroll"], as_dict=True)
            if not row:
                out["error"] = "Record not found"
            elif row.employee != emp:
                out["error"] = "Record does not belong to this worker"
            elif frappe.utils.cint(row.paid):
                out["error"] = "This day is already paid and cannot be edited"
            elif frappe.db.get_value("Work Actuals Employee", rowname, "payment_ref") and \
                 frappe.db.get_value("Work Management Payment",
                    frappe.db.get_value("Work Actuals Employee", rowname, "payment_ref"),
                    "workflow_state") == "Unpaid":
                out["error"] = ("This day is inside a payment awaiting accounts (" +
                    str(frappe.db.get_value("Work Actuals Employee", rowname, "payment_ref")) +
                    "). Return it to Unpaid first, then edit.")
            elif not frappe.utils.cint(row.count_in_payroll):
                out["error"] = "This row is not payroll-counted (salaried) — nothing to edit"
            else:
                pstate = frappe.db.get_value("Work Management Actuals", row.parent, "workflow_state")
                if pstate != "CONFIRMED":
                    out["error"] = "Actuals doc is not CONFIRMED (state: " + str(pstate) + ")"
                else:
                    old_qty = frappe.utils.flt(row.actual_quantity)
                    old_amt = frappe.utils.flt(row.amount)
                    rate = (old_amt / old_qty) if old_qty else frappe.utils.flt(
                        frappe.db.get_value("Work Management Actuals", row.parent, "rate"))
                    new_amt = round(new_qty * rate, 2)
                    frappe.db.set_value("Work Actuals Employee", rowname, "actual_quantity", new_qty, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", rowname, "amount", new_amt, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", rowname, "custom_reviewed", 0, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", rowname, "custom_reviewed_by", None, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", rowname, "custom_reviewed_at", None, update_modified=False)
                    tots = frappe.db.sql("""
                        SELECT COALESCE(SUM(actual_quantity),0) q, COALESCE(SUM(amount),0) p
                        FROM `tabWork Actuals Employee` WHERE parent=%s
                    """, (row.parent,), as_dict=True)
                    if tots:
                        frappe.db.set_value("Work Management Actuals", row.parent, "total_actual_qty", frappe.utils.flt(tots[0].q), update_modified=False)
                        frappe.db.set_value("Work Management Actuals", row.parent, "total_payment", frappe.utils.flt(tots[0].p), update_modified=False)
                    frappe.db.commit()
                    try:
                        frappe.get_doc("Work Management Actuals", row.parent).add_comment("Edited",
                            "Audit correction: " + (row.employee_name or emp) + " on " + str(row.work_date) +
                            " — qty " + str(old_qty) + " → " + str(new_qty) +
                            ", pay " + str(round(old_amt, 2)) + " → " + str(round(new_amt, 2)) +
                            " (by " + frappe.session.user + ")")
                    except Exception:
                        pass
                    out["rowname"] = rowname
                    out["qty"] = new_qty
                    out["amount"] = new_amt
                    out["rate"] = rate
                    out["parent"] = row.parent

    elif action == "pay_worker_review":
        # Stamp ONE worker's unpaid confirmed rows in the window as reviewed —
        # the audit trail between "Unpaid" and "sent to accounts".
        emp = frappe.form_dict.get("employee")
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        if not emp:
            out["error"] = "employee is required"
        else:
            rconds = "we.employee=%s AND ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0"
            rparams = [emp]
            if dfrom:
                rconds = rconds + " AND we.work_date >= %s"
                rparams.append(dfrom)
            if dto:
                rconds = rconds + " AND we.work_date <= %s"
                rparams.append(dto)
            rows = frappe.db.sql("""
                SELECT we.name rowname FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                WHERE """ + rconds + """
            """, tuple(rparams), as_dict=True)
            if not rows:
                out["error"] = "No unpaid confirmed rows to review in this window"
            else:
                now = frappe.utils.now()
                for r in rows:
                    frappe.db.set_value("Work Actuals Employee", r.rowname, "custom_reviewed", 1, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", r.rowname, "custom_reviewed_by", frappe.session.user, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", r.rowname, "custom_reviewed_at", now, update_modified=False)
                frappe.db.commit()
                out["employee"] = emp
                out["rows_reviewed"] = len(rows)
                out["reviewed_by"] = frappe.session.user

    elif action == "pay_worker_submit" and not CAN_SEND:
        out["error"] = ("Only the HR head, accounting or the general manager can send work to "
                        "accounts. You can review and audit, but not create the payment.")

    elif action == "pay_worker_submit":
        # Approve ONE worker's unpaid confirmed earnings and send them to accounts
        # as a single-worker payment run (workers are paid one at a time).
        emp = frappe.form_dict.get("employee")
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        if not emp:
            out["error"] = "employee is required"
        else:
            # Workers are paid by the WEEK. One payment per worker per COMPLETED
            # pay week, so payroll receives one Additional Salary line per week
            # instead of a single lump covering several. The week still in progress
            # is held back until it closes -- otherwise that week would need a
            # second document later and payroll would see it twice.
            # Start day, end day and pay day are three independent settings. The
            # week length follows from start and end, so a week need not be seven
            # days; the pay day may be the closing day or any day after it.
            wk_names = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
            wk_start_day = frappe.db.get_single_value("Work Management Settings", "pay_week_starts_on") or "Sunday"
            wk_end_day = frappe.db.get_single_value("Work Management Settings", "pay_week_ends_on") or "Saturday"
            wk_pay_day = frappe.db.get_single_value("Work Management Settings", "pay_day") or wk_end_day
            wk_start_wd = wk_names.index(wk_start_day) if wk_start_day in wk_names else 6
            wk_end_idx = wk_names.index(wk_end_day) if wk_end_day in wk_names else 5
            wk_pay_idx = wk_names.index(wk_pay_day) if wk_pay_day in wk_names else wk_end_idx
            wk_len = ((wk_end_idx - wk_start_wd) % 7) + 1
            wconds = ("we.employee=%s AND ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0"
                      " AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0"
                      " AND IFNULL(we.payment_ref,'')=''") + TW_ONLY
            wparams = [emp]
            if dfrom:
                wconds = wconds + " AND we.work_date >= %s"
                wparams.append(dfrom)
            if dto:
                wconds = wconds + " AND we.work_date <= %s"
                wparams.append(dto)
            wk_rows = frappe.db.sql("""
                SELECT we.work_date d, COALESCE(SUM(we.amount),0) a
                FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                WHERE """ + wconds + """
                GROUP BY we.work_date ORDER BY we.work_date
            """, tuple(wparams), as_dict=True)
            wk_today = frappe.utils.getdate(frappe.utils.today())
            wk_part_ok = frappe.utils.cint(frappe.db.get_single_value(
                "Work Management Settings", "allow_part_week_send"))
            wk_map = {}
            wk_outside = []
            for wr in wk_rows:
                wdd = frappe.utils.getdate(wr.d)
                wk_back = (wdd.weekday() - wk_start_wd) % 7
                if wk_back >= wk_len:
                    # the pay week is shorter than seven days and this weekday sits
                    # in the gap, so it belongs to no week -- reported, never dropped
                    wk_outside.append({"date": str(wr.d), "amount": frappe.utils.flt(wr.a)})
                    continue
                wk_s = frappe.utils.add_days(wdd, -wk_back)
                wk_e = frappe.utils.add_days(wk_s, wk_len - 1)
                wk_key = str(wk_s)
                if wk_key not in wk_map:
                    wk_map[wk_key] = {"week_from": str(wk_s), "week_to": str(wk_e),
                                      "amount": 0, "days": 0,
                                      "complete": 1 if (frappe.utils.getdate(wk_e) < wk_today or wk_part_ok) else 0}
                wk_map[wk_key]["amount"] = wk_map[wk_key]["amount"] + frappe.utils.flt(wr.a)
                wk_map[wk_key]["days"] = wk_map[wk_key]["days"] + 1
            wk_list = sorted(wk_map.values(), key=lambda x: x["week_from"])
            wk_ready = [w for w in wk_list if w["complete"]]
            wk_held = [w for w in wk_list if not w["complete"]]
            out["weeks"] = wk_list
            out["weeks_ready"] = wk_ready
            out["weeks_held"] = wk_held
            out["week_starts_on"] = wk_start_day
            out["week_ends_on"] = wk_end_day
            out["pay_day"] = wk_pay_day
            out["week_days"] = wk_len
            out["outside_any_week"] = wk_outside
            if frappe.utils.cint(frappe.form_dict.get("preview")):
                out["preview"] = 1
                out["would_create"] = len(wk_ready)
            elif not wk_ready:
                if wk_held:
                    out["error"] = ("Nothing to send yet - the only unpaid work is in the week still in "
                                    "progress (" + wk_held[0]["week_from"] + " to " + wk_held[0]["week_to"] +
                                    "). It can be sent once that week closes.")
                else:
                    out["error"] = "No unpaid confirmed earnings for this worker in the window"
            else:
                out["created"] = []
                wq_from = frappe.form_dict.get("from_date")
                wq_to = frappe.form_dict.get("to_date")
                for wk in wk_ready:
                    # clamp to the caller's window: a pay week can start before or
                    # end after the range on screen, and sweeping in work outside it
                    # would pay days the sender never saw
                    dfrom = wk["week_from"]
                    dto = wk["week_to"]
                    if wq_from and str(dfrom) < str(wq_from):
                        dfrom = wq_from
                    if wq_to and str(dto) > str(wq_to):
                        dto = wq_to
                    # IFNULL(payment_ref,'')='' matters: without it a second send re-claims rows
                    # that already sit on a payment, silently orphaning the first document
                    sconds = ("we.employee=%s AND ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0"
                               " AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0"
                               " AND IFNULL(we.payment_ref,'')=''") + TW_ONLY
                    sparams = [emp]
                    if dfrom:
                        sconds = sconds + " AND we.work_date >= %s"
                        sparams.append(dfrom)
                    if dto:
                        sconds = sconds + " AND we.work_date <= %s"
                        sparams.append(dto)
                    agg = frappe.db.sql("""
                        SELECT ac.name actuals, ac.farm farm, ac.task task, ac.block_section block,
                               ac.rate doc_rate, ac.assignment assignment,
                               ac.entered_by entered_by, ac.hr_approved_by hr_approved_by,
                               ac.gm_approved_by gm_approved_by, we.employee_name nm,
                               MIN(we.work_date) wfrom, MAX(we.work_date) wto,
                               COUNT(DISTINCT we.work_date) days,
                               COALESCE(SUM(we.actual_quantity),0) qty,
                               COALESCE(SUM(we.amount),0) owed,
                               MAX(we.custom_reviewed_at) reviewed_at,
                               MAX(we.custom_reviewed_by) reviewed_by
                        FROM `tabWork Actuals Employee` we
                        INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                        WHERE """ + sconds + """
                        GROUP BY ac.name, ac.farm, ac.task, ac.block_section, ac.rate, ac.assignment,
                                 ac.entered_by, ac.hr_approved_by, ac.gm_approved_by, we.employee_name
                        ORDER BY MIN(we.work_date)
                    """, tuple(sparams), as_dict=True)
                    total_owed = 0
                    for g in agg:
                        total_owed = total_owed + frappe.utils.flt(g.owed)
                    if not agg or total_owed <= 0:
                        continue
                    else:
                        ename = agg[0].nm or frappe.db.get_value("Employee", emp, "employee_name") or emp
                        d = frappe.new_doc("Work Management Payment")
                        d.run_title = "Worker payment — " + ename + " — " + frappe.utils.today()
                        d.company = DEFAULT_COMPANY
                        # payroll date = the first pay day on or after the week ends, so
                        # setting the pay day to the closing day pays on that day
                        pd_val = dto
                        pd_guard = 0
                        while frappe.utils.getdate(pd_val).weekday() != wk_pay_idx and pd_guard < 7:
                            pd_val = frappe.utils.add_days(pd_val, 1)
                            pd_guard = pd_guard + 1
                        d.payroll_date = pd_val
                        d.prepared_by = frappe.session.user
                        try:
                            if dfrom:
                                d.period_from = dfrom
                            if dto:
                                d.period_to = dto
                        except Exception:
                            pass
                        # one traceable line per actuals doc this worker earned on, carrying
                        # the full accountability chain from the review sheet: who assigned
                        # the job, who entered actuals, and every approver.
                        asg_cache = {}
                        total_days = 0
                        total_qty = 0
                        rv_by = None
                        rv_at = None
                        for g in agg:
                            if frappe.utils.flt(g.owed) <= 0:
                                continue
                            ai = None
                            if g.assignment:
                                ai = asg_cache.get(g.assignment)
                                if ai is None:
                                    ai = frappe.db.get_value("Work Management Assigner", g.assignment,
                                        ["assigned_by", "approved_by"], as_dict=True)
                                    asg_cache[g.assignment] = ai
                            qty = frappe.utils.flt(g.qty)
                            owed = frappe.utils.flt(g.owed)
                            row = d.append("lines", {})
                            row.actuals = g.actuals
                            row.employee = emp
                            row.employee_name = ename
                            row.farm = g.farm
                            row.task = g.task
                            row.block = g.block
                            row.work_from = g.wfrom
                            row.work_to = g.wto
                            row.days = g.days
                            row.qty = qty
                            row.rate = frappe.utils.flt(g.doc_rate) or ((owed / qty) if qty else 0)
                            row.assignment = g.assignment
                            row.assigned_by = ai.assigned_by if ai else None
                            row.fm_approved_by = ai.approved_by if ai else None
                            row.entered_by = g.entered_by
                            row.hr_approved_by = g.hr_approved_by
                            row.gm_approved_by = g.gm_approved_by
                            row.paid_workers = 1
                            row.amount = owed
                            total_days = total_days + frappe.utils.cint(g.days)
                            total_qty = total_qty + qty
                            if g.reviewed_at and (not rv_at or str(g.reviewed_at) > str(rv_at)):
                                rv_at = g.reviewed_at
                                rv_by = g.reviewed_by
                        # worker-centric header: one payment entry per employee
                        d.employee = emp
                        d.employee_name = ename
                        d.farm = agg[0].farm
                        d.total_days = total_days
                        d.total_qty = total_qty
                        d.amount = total_owed
                        d.total_workers = 1
                        d.total_actuals = len(d.lines)
                        d.flags.ignore_permissions = True
                        d.insert(ignore_permissions=True)
                        frappe.db.set_value("Work Management Payment", d.name, "workflow_state", "Unpaid", update_modified=False)
                        # stamp the reference on the included rows (NOT paid yet) so the
                        # worker shows as "Sent to accounts" until accounts releases it
                        refrows = frappe.db.sql("""
                            SELECT we.name rowname FROM `tabWork Actuals Employee` we
                            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                            WHERE """ + sconds + """
                        """, tuple(sparams), as_dict=True)
                        subnow = frappe.utils.now()
                        for rr in refrows:
                            frappe.db.set_value("Work Actuals Employee", rr.rowname, "payment_ref", d.name, update_modified=False)
                            frappe.db.set_value("Work Actuals Employee", rr.rowname, "custom_reviewed", 1, update_modified=False)
                            frappe.db.set_value("Work Actuals Employee", rr.rowname, "custom_reviewed_by", frappe.session.user, update_modified=False)
                            frappe.db.set_value("Work Actuals Employee", rr.rowname, "custom_reviewed_at", subnow, update_modified=False)
                        frappe.db.commit()
                        out["created"].append({
                            "name": d.name, "workflow_state": "Unpaid",
                            "employee": emp, "employee_name": ename,
                            "week_from": dfrom, "week_to": dto,
                            "payroll_date": str(frappe.db.get_value("Work Management Payment", d.name, "payroll_date") or ""),
                            "amount": total_owed,
                            "days": sum(frappe.utils.cint(x.days) for x in agg)})

    elif action == "pay_bulk_review":
        # Stamp SEVERAL workers' unpaid confirmed rows as reviewed in one call.
        # Same stamps as pay_worker_review, looped; employees is a CSV list.
        emps_raw = frappe.form_dict.get("employees")
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        emp_list = []
        if emps_raw:
            for e in emps_raw.split(","):
                ev = e.strip()
                if ev and ev not in emp_list:
                    emp_list.append(ev)
        if not emp_list:
            out["error"] = "employees is required (CSV)"
        else:
            now = frappe.utils.now()
            results = []
            total_rows = 0
            for emp in emp_list:
                rconds = "we.employee=%s AND ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0"
                rparams = [emp]
                if dfrom:
                    rconds = rconds + " AND we.work_date >= %s"
                    rparams.append(dfrom)
                if dto:
                    rconds = rconds + " AND we.work_date <= %s"
                    rparams.append(dto)
                rows = frappe.db.sql("""
                    SELECT we.name rowname FROM `tabWork Actuals Employee` we
                    INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                    WHERE """ + rconds + """
                """, tuple(rparams), as_dict=True)
                if not rows:
                    results.append({"employee": emp, "rows": 0, "error": "no unpaid confirmed rows"})
                    continue
                for r in rows:
                    frappe.db.set_value("Work Actuals Employee", r.rowname, "custom_reviewed", 1, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", r.rowname, "custom_reviewed_by", frappe.session.user, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", r.rowname, "custom_reviewed_at", now, update_modified=False)
                total_rows = total_rows + len(rows)
                results.append({"employee": emp, "rows": len(rows)})
            frappe.db.commit()
            out["results"] = results
            out["workers_reviewed"] = len([r for r in results if not r.get("error")])
            out["rows_reviewed"] = total_rows
            out["reviewed_by"] = frappe.session.user

    elif action == "pay_bulk_submit" and not CAN_SEND:
        out["error"] = ("Only the HR head, accounting or the general manager can send work to "
                        "accounts. You can review and audit, but not create the payment.")

    elif action == "pay_bulk_submit":
        # Send SEVERAL reviewed workers to accounts in one call: one Work
        # Management Payment per employee (same shape as pay_worker_submit).
        # A worker with any unreviewed unpaid rows is skipped — review first.
        emps_raw = frappe.form_dict.get("employees")
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        emp_list = []
        if emps_raw:
            for e in emps_raw.split(","):
                ev = e.strip()
                if ev and ev not in emp_list:
                    emp_list.append(ev)
        if not emp_list:
            out["error"] = "employees is required (CSV)"
        else:
            results = []
            sent = 0
            sent_total = 0
            bw_from = dfrom
            bw_to = dto
            bw_names = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
            bw_start_day = frappe.db.get_single_value("Work Management Settings", "pay_week_starts_on") or "Sunday"
            bw_end_day = frappe.db.get_single_value("Work Management Settings", "pay_week_ends_on") or "Saturday"
            bw_pay_day = frappe.db.get_single_value("Work Management Settings", "pay_day") or bw_end_day
            bw_start_wd = bw_names.index(bw_start_day) if bw_start_day in bw_names else 6
            bw_end_idx = bw_names.index(bw_end_day) if bw_end_day in bw_names else 5
            bw_pay_idx = bw_names.index(bw_pay_day) if bw_pay_day in bw_names else bw_end_idx
            bw_len = ((bw_end_idx - bw_start_wd) % 7) + 1
            bw_today = frappe.utils.getdate(frappe.utils.today())
            bw_part_ok = frappe.utils.cint(frappe.db.get_single_value(
                "Work Management Settings", "allow_part_week_send"))
            for emp in emp_list:
                # same weekly rule as the single send: one payment per worker per
                # COMPLETED pay week, with the week in progress held back
                dfrom = bw_from
                dto = bw_to
                bconds = ("we.employee=%s AND ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0"
                           " AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0"
                           " AND IFNULL(we.payment_ref,'')=''") + TW_ONLY
                bparams = [emp]
                if dfrom:
                    bconds = bconds + " AND we.work_date >= %s"
                    bparams.append(dfrom)
                if dto:
                    bconds = bconds + " AND we.work_date <= %s"
                    bparams.append(dto)
                bwk_rows = frappe.db.sql("""
                    SELECT we.work_date d FROM `tabWork Actuals Employee` we
                    INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                    WHERE """ + bconds + """
                    GROUP BY we.work_date
                """, tuple(bparams), as_dict=True)
                bwk = {}
                for br in bwk_rows:
                    bdd = frappe.utils.getdate(br.d)
                    bback = (bdd.weekday() - bw_start_wd) % 7
                    if bback >= bw_len:
                        continue
                    bs = frappe.utils.add_days(bdd, -bback)
                    be = frappe.utils.add_days(bs, bw_len - 1)
                    if frappe.utils.getdate(be) < bw_today or bw_part_ok:
                        bwk[str(bs)] = {"week_from": str(bs), "week_to": str(be)}
                for wk in sorted(bwk.values(), key=lambda x: x["week_from"]):
                    dfrom = wk["week_from"]
                    dto = wk["week_to"]
                    if bw_from and str(dfrom) < str(bw_from):
                        dfrom = bw_from
                    if bw_to and str(dto) > str(bw_to):
                        dto = bw_to
                    # IFNULL(payment_ref,'')='' matters: without it a second send re-claims rows
                    # that already sit on a payment, silently orphaning the first document
                    sconds = "we.employee=%s AND ac.workflow_state='CONFIRMED' AND IFNULL(we.paid,0)=0 AND IFNULL(we.count_in_payroll,0)=1 AND we.amount>0 AND IFNULL(we.payment_ref,'')=''"
                    sparams = [emp]
                    if dfrom:
                        sconds = sconds + " AND we.work_date >= %s"
                        sparams.append(dfrom)
                    if dto:
                        sconds = sconds + " AND we.work_date <= %s"
                        sparams.append(dto)
                    agg = frappe.db.sql("""
                        SELECT ac.name actuals, ac.farm farm, ac.task task, ac.block_section block,
                               ac.rate doc_rate, ac.assignment assignment,
                               ac.entered_by entered_by, ac.hr_approved_by hr_approved_by,
                               ac.gm_approved_by gm_approved_by, we.employee_name nm,
                               MIN(we.work_date) wfrom, MAX(we.work_date) wto,
                               COUNT(DISTINCT we.work_date) days,
                               COALESCE(SUM(we.actual_quantity),0) qty,
                               COALESCE(SUM(we.amount),0) owed,
                               MAX(we.custom_reviewed_at) reviewed_at,
                               MAX(we.custom_reviewed_by) reviewed_by
                        FROM `tabWork Actuals Employee` we
                        INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                        WHERE """ + sconds + """
                        GROUP BY ac.name, ac.farm, ac.task, ac.block_section, ac.rate, ac.assignment,
                                 ac.entered_by, ac.hr_approved_by, ac.gm_approved_by, we.employee_name
                        ORDER BY MIN(we.work_date)
                    """, tuple(sparams), as_dict=True)
                    total_owed = 0
                    for g in agg:
                        total_owed = total_owed + frappe.utils.flt(g.owed)
                    if not agg or total_owed <= 0:
                        results.append({"employee": emp, "error": "no unpaid confirmed earnings in window"})
                        continue
                    ename = agg[0].nm or frappe.db.get_value("Employee", emp, "employee_name") or emp
                    d = frappe.new_doc("Work Management Payment")
                    d.run_title = "Worker payment — " + ename + " — " + frappe.utils.today()
                    d.company = DEFAULT_COMPANY
                    # payroll date = the day the week closes, which IS the pay day, so a
                    # week's earnings land on one known date for everyone
                    # payroll date = the first pay day on or after the week ends
                    pd_val = dto
                    pd_guard = 0
                    while frappe.utils.getdate(pd_val).weekday() != bw_pay_idx and pd_guard < 7:
                        pd_val = frappe.utils.add_days(pd_val, 1)
                        pd_guard = pd_guard + 1
                    d.payroll_date = pd_val
                    d.prepared_by = frappe.session.user
                    try:
                        if dfrom:
                            d.period_from = dfrom
                        if dto:
                            d.period_to = dto
                    except Exception:
                        pass
                    asg_cache = {}
                    total_days = 0
                    total_qty = 0
                    rv_by = None
                    rv_at = None
                    for g in agg:
                        if frappe.utils.flt(g.owed) <= 0:
                            continue
                        ai = None
                        if g.assignment:
                            ai = asg_cache.get(g.assignment)
                            if ai is None:
                                ai = frappe.db.get_value("Work Management Assigner", g.assignment,
                                    ["assigned_by", "approved_by"], as_dict=True)
                                asg_cache[g.assignment] = ai
                        qty = frappe.utils.flt(g.qty)
                        owed = frappe.utils.flt(g.owed)
                        row = d.append("lines", {})
                        row.actuals = g.actuals
                        row.employee = emp
                        row.employee_name = ename
                        row.farm = g.farm
                        row.task = g.task
                        row.block = g.block
                        row.work_from = g.wfrom
                        row.work_to = g.wto
                        row.days = g.days
                        row.qty = qty
                        row.rate = frappe.utils.flt(g.doc_rate) or ((owed / qty) if qty else 0)
                        row.assignment = g.assignment
                        row.assigned_by = ai.assigned_by if ai else None
                        row.fm_approved_by = ai.approved_by if ai else None
                        row.entered_by = g.entered_by
                        row.hr_approved_by = g.hr_approved_by
                        row.gm_approved_by = g.gm_approved_by
                        row.paid_workers = 1
                        row.amount = owed
                        total_days = total_days + frappe.utils.cint(g.days)
                        total_qty = total_qty + qty
                        if g.reviewed_at and (not rv_at or str(g.reviewed_at) > str(rv_at)):
                            rv_at = g.reviewed_at
                            rv_by = g.reviewed_by
                    d.employee = emp
                    d.employee_name = ename
                    d.farm = agg[0].farm
                    d.total_days = total_days
                    d.total_qty = total_qty
                    d.amount = total_owed
                    d.total_workers = 1
                    d.total_actuals = len(d.lines)
                    d.flags.ignore_permissions = True
                    d.insert(ignore_permissions=True)
                    frappe.db.set_value("Work Management Payment", d.name, "workflow_state", "Unpaid", update_modified=False)
                    refrows = frappe.db.sql("""
                        SELECT we.name rowname FROM `tabWork Actuals Employee` we
                        INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                        WHERE """ + sconds + """
                    """, tuple(sparams), as_dict=True)
                    bulknow = frappe.utils.now()
                    for rr in refrows:
                        frappe.db.set_value("Work Actuals Employee", rr.rowname, "payment_ref", d.name, update_modified=False)
                        frappe.db.set_value("Work Actuals Employee", rr.rowname, "custom_reviewed", 1, update_modified=False)
                        frappe.db.set_value("Work Actuals Employee", rr.rowname, "custom_reviewed_by", frappe.session.user, update_modified=False)
                        frappe.db.set_value("Work Actuals Employee", rr.rowname, "custom_reviewed_at", bulknow, update_modified=False)
                    sent = sent + 1
                    sent_total = sent_total + total_owed
                    results.append({"employee": emp, "employee_name": ename, "name": d.name,
                                    "week_from": dfrom, "week_to": dto, "amount": total_owed})
            frappe.db.commit()
            out["results"] = results
            out["sent"] = sent
            out["sent_total"] = sent_total
            out["errors"] = len([r for r in results if r.get("error")])

    elif action == "pay_absent_conflicts":
        # AUDIT: every confirmed worker-day with money recorded on a day that
        # worker was marked ABSENT (submitted attendance). Scan time attached so
        # reviewers can tell "attendance wrongly marked" (has a scan) from a
        # possible ghost entry (no scan either). Optional farm + date filters.
        cfarm = (frappe.form_dict.get("farm") or "").strip()
        cfrom = frappe.form_dict.get("from_date")
        cto = frappe.form_dict.get("to_date")
        cconds = "ac.workflow_state='CONFIRMED' AND we.amount > 0"
        cparams = []
        if cfarm:
            cconds = cconds + " AND TRIM(ac.farm) = TRIM(%s)"
            cparams.append(cfarm)
        if cfrom:
            cconds = cconds + " AND we.work_date >= %s"
            cparams.append(cfrom)
        if cto:
            cconds = cconds + " AND we.work_date <= %s"
            cparams.append(cto)
        crows = frappe.db.sql("""
            SELECT we.employee, we.employee_name, ac.farm, ac.task, ac.name actuals,
                   we.work_date wdate, we.actual_quantity qty, we.amount,
                   IFNULL(we.paid,0) paid, we.payment_ref run_ref,
                   ac.entered_by entered_by
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            INNER JOIN `tabAttendance` att ON att.employee = we.employee
                  AND att.attendance_date = we.work_date
                  AND att.docstatus = 1 AND att.status = 'Absent'
            WHERE """ + cconds + """
            ORDER BY we.work_date DESC, we.employee
            LIMIT 2000
        """, tuple(cparams), as_dict=True)
        # scan evidence for those exact worker-days
        scan_ev = {}
        if crows:
            cemps = tuple(set([r.employee for r in crows]))
            cdates = tuple(set([str(r.wdate) for r in crows]))
            for r2 in frappe.db.sql("""
                SELECT employee, DATE(`time`) d, MIN(`time`) t FROM `tabEmployee Checkin`
                WHERE employee IN %s AND DATE(`time`) IN %s
                GROUP BY employee, DATE(`time`)
            """, (cemps, cdates), as_dict=True):
                scan_ev[(r2.employee, str(r2.d))] = str(r2.t)[11:16]
        rows_out = []
        tot_amt = 0
        tot_paid = 0
        wset = {}
        for r in crows:
            wd = str(r.wdate)
            amt = frappe.utils.flt(r.amount)
            tot_amt = tot_amt + amt
            if frappe.utils.cint(r.paid):
                tot_paid = tot_paid + amt
            wset[r.employee] = 1
            rows_out.append({
                "employee": r.employee, "employee_name": r.employee_name,
                "farm": r.farm, "task": r.task, "actuals": r.actuals,
                "wdate": wd, "qty": frappe.utils.flt(r.qty), "amount": amt,
                "paid": frappe.utils.cint(r.paid), "run_ref": r.run_ref,
                "entered_by": r.entered_by,
                "scan_in": scan_ev.get((r.employee, wd)),
            })
        out["rows"] = rows_out
        out["summary"] = {
            "rows": len(rows_out), "workers": len(wset),
            "amount": tot_amt, "paid_amount": tot_paid,
            "unpaid_amount": tot_amt - tot_paid,
            "with_scan": len([x for x in rows_out if x["scan_in"]]),
            "no_scan": len([x for x in rows_out if not x["scan_in"]]),
        }

    elif action == "pay_discrepancies":
        # AUDIT / DISCREPANCY ENGINE — every check is a way money can leak or a
        # record can lie. Each returns auditable rows (worker, day, doc) so the
        # reviewer can open the worker's sheet or the actuals doc directly.
        dfarm = (frappe.form_dict.get("farms") or "").strip()
        dfrom = frappe.form_dict.get("from_date")
        dto = frappe.form_dict.get("to_date")
        if not dfrom:
            dfrom = str(frappe.utils.add_days(frappe.utils.today(), -31))
        if not dto:
            dto = str(frappe.utils.today())
        # per-check enable toggles (Work Management Settings; default ON)
        disc_on = {}
        for dk in ("disc_absent_paid", "disc_ghost_days", "disc_leave_paid", "disc_off_paid",
                   "disc_rate_mismatch", "disc_multi_farm", "disc_self_approved", "disc_left_earning",
                   "disc_no_pay", "disc_dup_day", "disc_inactive_assigned"):
            val = 1
            try:
                val = frappe.utils.cint(frappe.db.get_single_value("Work Management Settings", dk))
            except Exception:
                val = 1
            disc_on[dk] = val
        dconds = "ac.workflow_state='CONFIRMED' AND we.amount > 0 AND we.work_date BETWEEN %s AND %s"
        dparams = [dfrom, dto]
        farm_list_d = []
        if dfarm:
            for f in dfarm.split(","):
                fv = f.strip()
                if fv:
                    farm_list_d.append(fv)
        if farm_list_d:
            dconds = dconds + " AND TRIM(ac.farm) IN %s"
            dparams.append(tuple(farm_list_d))
        base_rows = frappe.db.sql("""
            SELECT we.name rowname, we.employee, we.employee_name, ac.farm, ac.task,
                   ac.name actuals, we.work_date wdate, we.actual_quantity qty,
                   we.amount, IFNULL(we.paid,0) paid, we.payment_ref run_ref,
                   ac.rate doc_rate, IFNULL(we.count_in_payroll,0) in_pay,
                   ac.entered_by entered_by
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + dconds + """
            ORDER BY we.work_date DESC
            LIMIT 30000
        """, tuple(dparams), as_dict=True)
        # ---- evidence maps for the window ----
        demps = tuple(set([r.employee for r in base_rows])) or ("__none__",)
        scan_ev = {}
        att_ev = {}
        for r2 in frappe.db.sql("""
            SELECT employee, DATE(`time`) d, MIN(`time`) t FROM `tabEmployee Checkin`
            WHERE employee IN %s AND DATE(`time`) BETWEEN %s AND %s
            GROUP BY employee, DATE(`time`)
        """, (demps, dfrom, dto), as_dict=True):
            scan_ev[(r2.employee, str(r2.d))] = str(r2.t)[11:16]
        for r2 in frappe.db.sql("""
            SELECT employee, attendance_date d, status FROM `tabAttendance`
            WHERE docstatus = 1 AND employee IN %s AND attendance_date BETWEEN %s AND %s
        """, (demps, dfrom, dto), as_dict=True):
            kk2 = (r2.employee, str(r2.d))
            # corrected attendance: a Present-class record beats an Absent one
            if r2.status in ('Present', 'Half Day', 'Work From Home'):
                att_ev[kk2] = r2.status
            elif att_ev.get(kk2) not in ('Present', 'Half Day', 'Work From Home'):
                att_ev[kk2] = r2.status
        leave_ev = {}
        for r2 in frappe.db.sql("""
            SELECT employee, leave_type, from_date, to_date FROM `tabLeave Application`
            WHERE docstatus < 2 AND (status='Approved' OR docstatus=1)
              AND from_date <= %s AND to_date >= %s AND employee IN %s
        """, (dto, dfrom, demps), as_dict=True):
            lst = leave_ev.get(r2.employee)
            if lst is None:
                lst = []
                leave_ev[r2.employee] = lst
            lst.append((str(r2.from_date), str(r2.to_date), r2.leave_type or "leave"))
        hl_ev = {}
        for r2 in frappe.db.sql("""
            SELECT name, holiday_list FROM `tabEmployee`
            WHERE name IN %s AND IFNULL(holiday_list,'') != ''
        """, (demps,), as_dict=True):
            hl_ev[r2.name] = r2.holiday_list
        off_ev = {}
        if hl_ev:
            for r2 in frappe.db.sql("""
                SELECT parent, holiday_date FROM `tabHoliday`
                WHERE parent IN %s AND holiday_date BETWEEN %s AND %s
            """, (tuple(set(hl_ev.values())), dfrom, dto), as_dict=True):
                off_ev[(r2.parent, str(r2.holiday_date))] = 1
        # ---- single pass: bucket rows into the presence-based checks ----
        today_d = str(frappe.utils.today())
        b_absent = []
        b_ghost = []
        b_leave = []
        b_off = []
        b_rate = []
        for r in base_rows:
            wd = str(r.wdate)
            rr = {"employee": r.employee, "employee_name": r.employee_name,
                  "farm": r.farm, "task": r.task, "actuals": r.actuals, "wdate": wd,
                  "qty": frappe.utils.flt(r.qty), "amount": frappe.utils.flt(r.amount),
                  "paid": frappe.utils.cint(r.paid), "run_ref": r.run_ref,
                  "entered_by": r.entered_by,
                  "scan_in": scan_ev.get((r.employee, wd)),
                  "att_status": att_ev.get((r.employee, wd))}
            astat = att_ev.get((r.employee, wd))
            if astat == "Absent":
                b_absent.append(rr)
            elif wd <= today_d and not rr["scan_in"] and not astat:
                b_ghost.append(rr)
            onlv = 0
            for lv in leave_ev.get(r.employee, []):
                if lv[0] <= wd <= lv[1]:
                    rr2 = dict(rr)
                    rr2["leave_type"] = lv[2]
                    b_leave.append(rr2)
                    onlv = 1
                    break
            if not onlv and hl_ev.get(r.employee) and off_ev.get((hl_ev[r.employee], wd)):
                b_off.append(rr)
            # amount should equal qty x doc rate for payroll rows
            if frappe.utils.cint(r.in_pay) and frappe.utils.flt(r.doc_rate) > 0:
                expect = frappe.utils.flt(r.qty) * frappe.utils.flt(r.doc_rate)
                if abs(expect - frappe.utils.flt(r.amount)) > 0.5:
                    rr3 = dict(rr)
                    rr3["expected"] = expect
                    rr3["rate"] = frappe.utils.flt(r.doc_rate)
                    b_rate.append(rr3)
        # ---- same worker earning on 2+ farms the same day ----
        b_multi = []
        mf = frappe.db.sql("""
            SELECT we.employee, we.employee_name, we.work_date wdate,
                   COUNT(DISTINCT ac.farm) farms,
                   GROUP_CONCAT(DISTINCT ac.farm) farm_list,
                   GROUP_CONCAT(DISTINCT ac.name) docs,
                   COALESCE(SUM(we.amount),0) amount
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + dconds + """
            GROUP BY we.employee, we.employee_name, we.work_date
            HAVING COUNT(DISTINCT ac.farm) > 1
            ORDER BY we.work_date DESC LIMIT 300
        """, tuple(dparams), as_dict=True)
        for r in mf:
            b_multi.append({"employee": r.employee, "employee_name": r.employee_name,
                            "wdate": str(r.wdate), "farms": r.farm_list, "actuals": r.docs,
                            "amount": frappe.utils.flt(r.amount)})
        # ---- self-approval: the person who entered the actuals also approved them ----
        sconds2 = "ac.workflow_state='CONFIRMED' AND ac.entry_date BETWEEN %s AND %s"
        sparams2 = [dfrom, dto]
        if farm_list_d:
            sconds2 = sconds2 + " AND TRIM(ac.farm) IN %s"
            sparams2.append(tuple(farm_list_d))
        b_self = []
        for r in frappe.db.sql("""
            SELECT ac.name actuals, ac.farm, ac.task, ac.entered_by,
                   ac.hr_approved_by, ac.gm_approved_by, ac.entry_date,
                   ac.total_payment amount
            FROM `tabWork Management Actuals` ac
            WHERE """ + sconds2 + """
              AND (ac.entered_by = ac.hr_approved_by OR ac.entered_by = ac.gm_approved_by)
            ORDER BY ac.entry_date DESC LIMIT 300
        """, tuple(sparams2), as_dict=True):
            b_self.append({"actuals": r.actuals, "farm": r.farm, "task": r.task,
                           "entered_by": r.entered_by,
                           "hr_approved_by": r.hr_approved_by, "gm_approved_by": r.gm_approved_by,
                           "wdate": str(r.entry_date), "amount": frappe.utils.flt(r.amount)})
        # ---- worker marked Left but still earning after their left date ----
        b_left = []
        for r in frappe.db.sql("""
            SELECT we.employee, we.employee_name, ac.farm, ac.task, ac.name actuals,
                   we.work_date wdate, we.amount, wae.left_date
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            INNER JOIN `tabWork Management Assigner` a2 ON ac.assignment = a2.name
            INNER JOIN `tabWork Assignment Employee` wae ON wae.parent = a2.name
                  AND wae.employee = we.employee AND wae.status = 'Left'
                  AND wae.left_date IS NOT NULL AND we.work_date > wae.left_date
            WHERE """ + dconds + """
            ORDER BY we.work_date DESC LIMIT 300
        """, tuple(dparams), as_dict=True):
            b_left.append({"employee": r.employee, "employee_name": r.employee_name,
                           "farm": r.farm, "task": r.task, "actuals": r.actuals,
                           "wdate": str(r.wdate), "left_date": str(r.left_date),
                           "amount": frappe.utils.flt(r.amount)})
        # ---- recorded work valued at ZERO: qty entered but the row paid nothing,
        # although the doc has a rate and the worker is (now) a Task Worker. Happens
        # when the employment-type lookup failed at entry time. ----
        b_nopay = []
        npconds = "ac.workflow_state='CONFIRMED' AND we.actual_quantity > 0 AND IFNULL(we.amount,0) <= 0 AND IFNULL(ac.rate,0) > 0 AND IFNULL(we.paid,0) = 0 AND we.work_date BETWEEN %s AND %s"
        npparams = [dfrom, dto]
        if farm_list_d:
            npconds = npconds + " AND TRIM(ac.farm) IN %s"
            npparams.append(tuple(farm_list_d))
        for r in frappe.db.sql("""
            SELECT we.name rowname, we.employee, we.employee_name, ac.farm, ac.task,
                   ac.name actuals, we.work_date wdate, we.actual_quantity qty,
                   ac.rate doc_rate
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            INNER JOIN `tabEmployee` emp ON emp.name = we.employee
            WHERE """ + npconds + """
              AND emp.employment_type = 'Task Worker'
            ORDER BY we.work_date DESC LIMIT 300
        """, tuple(npparams), as_dict=True):
            wd = str(r.wdate)
            b_nopay.append({"employee": r.employee, "employee_name": r.employee_name,
                            "farm": r.farm, "task": r.task, "actuals": r.actuals,
                            "wdate": wd, "qty": frappe.utils.flt(r.qty), "amount": 0,
                            "rate": frappe.utils.flt(r.doc_rate),
                            "should_be": frappe.utils.flt(r.qty) * frappe.utils.flt(r.doc_rate),
                            "rowname": r.rowname,
                            "scan_in": scan_ev.get((r.employee, wd)),
                            "att_status": att_ev.get((r.employee, wd))})
        # ---- duplicate day entries: same worker + task + date recorded in more
        # than one document — double pay from overlapping assignments. ----
        b_dup = []
        for r in frappe.db.sql("""
            SELECT we.employee, we.employee_name, ac.farm, ac.task, we.work_date wdate,
                   COUNT(*) copies, COALESCE(SUM(we.amount),0) total_amt,
                   COALESCE(MAX(we.amount),0) keep_amt,
                   GROUP_CONCAT(DISTINCT ac.name) docs,
                   GROUP_CONCAT(DISTINCT ac.entered_by) enterers,
                   MIN(IFNULL(we.paid,0)) min_paid
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + dconds + """ AND we.actual_quantity > 0
            GROUP BY we.employee, we.employee_name, ac.farm, ac.task, we.work_date
            HAVING COUNT(*) > 1
            ORDER BY we.work_date DESC LIMIT 300
        """, tuple(dparams), as_dict=True):
            b_dup.append({"employee": r.employee, "employee_name": r.employee_name,
                          "farm": r.farm, "task": r.task, "wdate": str(r.wdate),
                          "copies": frappe.utils.cint(r.copies),
                          "amount": frappe.utils.flt(r.total_amt) - frappe.utils.flt(r.keep_amt),
                          "total_amt": frappe.utils.flt(r.total_amt),
                          "actuals": r.docs, "entered_by": r.enterers,
                          "paid": frappe.utils.cint(r.min_paid)})
        # ---- employees deactivated in HR but still Active on live assignments:
        # current-state check (ignores the date window) — these people can still
        # have quantities entered against them. ----
        b_inactive = []
        iconds = ""
        iparams = []
        if farm_list_d:
            iconds = " AND TRIM(a.farm) IN %s"
            iparams.append(tuple(farm_list_d))
        for r in frappe.db.sql("""
            SELECT we.name rowname, we.employee, we.employee_name, a.name assignment,
                   a.farm, a.task, a.from_date afrom, a.to_date ato, emp.status emp_status
            FROM `tabWork Assignment Employee` we
            INNER JOIN `tabWork Management Assigner` a ON we.parent = a.name
            INNER JOIN `tabEmployee` emp ON emp.name = we.employee
            WHERE a.workflow_state IN ('Pending Farm Manager','Pending HR Head','Pending GM','Assigned')
              AND IFNULL(we.status,'Active') = 'Active'
              AND emp.status != 'Active'
              """ + iconds + """
            ORDER BY a.farm, we.employee_name LIMIT 300
        """, tuple(iparams), as_dict=True):
            b_inactive.append({"employee": r.employee, "employee_name": r.employee_name,
                               "emp_status": r.emp_status, "farm": r.farm, "task": r.task,
                               "assignment": r.assignment, "wdate": str(r.afrom) + " → " + str(r.ato),
                               "amount": 0})
        checks = [
            {"key": "inactive_assigned", "title": "Left the company but still on live assignments",
             "about": "The employee is Inactive/Left in HR, yet still marked Active on a live assignment — quantities can still be recorded against them. Release them via a substitution/swap, or turn on 'Auto-release inactive employees from assignments' in Work Management Settings to handle this automatically.",
             "rows": b_inactive},
            {"key": "dup_day", "title": "Paid twice for the same day",
             "about": "The same worker, task and date recorded in more than one actuals document — usually two overlapping assignments for one task. The KES figure is the EXCESS beyond one copy. Zero the duplicate day with Edit in the worker's review sheet.",
             "rows": b_dup},
            {"key": "absent_paid", "title": "Paid on marked-Absent days",
             "about": "Money recorded on a day the worker's submitted attendance says Absent. A scan time means the attendance is probably wrong; no scan means the entry itself needs scrutiny.",
             "rows": b_absent},
            {"key": "ghost_days", "title": "No presence evidence at all",
             "about": "Work recorded on a day with no biometric scan and no attendance record of any kind — presence unknown. Could be a reader gap or a ghost entry.",
             "rows": b_ghost},
            {"key": "leave_paid", "title": "Earning while on approved leave",
             "about": "Task pay recorded on days covered by an approved Leave Application — possible double payment (leave pay + task pay).",
             "rows": b_leave},
            {"key": "off_paid", "title": "Work recorded on off days / holidays",
             "about": "Pay on the worker's weekly off or a public holiday. May be legitimate overtime — but should be deliberate, not accidental.",
             "rows": b_off},
            {"key": "rate_mismatch", "title": "Amount doesn't match qty × rate",
             "about": "Payroll rows where the stored amount differs from quantity × the document rate — edited or corrupted values.",
             "rows": b_rate},
            {"key": "multi_farm_day", "title": "Two farms, one day",
             "about": "The same worker earning on more than one farm on the same date — physically doubtful; usually a wrong worker picked.",
             "rows": b_multi},
            {"key": "self_approved", "title": "Entered and approved by the same person",
             "about": "Actuals documents where the person who entered the quantities also gave the HR or GM approval — no independent check.",
             "rows": b_self},
            {"key": "left_but_earning", "title": "Earning after leaving the job",
             "about": "Rows dated after the worker was marked Left on that assignment — a substituted/released worker still collecting days.",
             "rows": b_left},
            {"key": "no_pay", "title": "Recorded work with no pay",
             "about": "Quantities recorded but the row valued at ZERO although the document has a rate and the worker is a Task Worker — the worker-type lookup failed at entry, so these people will never be paid for the work. Revalue to qty × rate.",
             "rows": b_nopay},
        ]
        toggle_map = {"inactive_assigned": "disc_inactive_assigned",
                      "dup_day": "disc_dup_day", "no_pay": "disc_no_pay",
                      "absent_paid": "disc_absent_paid", "ghost_days": "disc_ghost_days",
                      "leave_paid": "disc_leave_paid", "off_paid": "disc_off_paid",
                      "rate_mismatch": "disc_rate_mismatch", "multi_farm_day": "disc_multi_farm",
                      "self_approved": "disc_self_approved", "left_but_earning": "disc_left_earning"}
        for c in checks:
            if not disc_on.get(toggle_map.get(c["key"]), 1):
                c["rows"] = []
                c["disabled"] = 1
            amts = 0
            wku = {}
            for x in c["rows"]:
                amts = amts + frappe.utils.flt(x.get("should_be") if c["key"] == "no_pay" else x.get("amount"))
                if x.get("employee"):
                    wku[x["employee"]] = 1
            c["count"] = len(c["rows"])
            c["workers"] = len(wku)
            c["amount"] = amts
            c["rows"] = c["rows"][:200]
        out["checks"] = checks
        out["window"] = {"from": dfrom, "to": dto}
        out["scanned_rows"] = len(base_rows)

    elif action == "pay_fix_unvalued":
        # Repair rows found by the "Recorded work with no pay" check: a Task
        # Worker's row that valued at zero because the type lookup failed at entry.
        # Revalues to qty x doc rate, restores payroll counting, re-sums the parent
        # and leaves an audit comment. Only unpaid rows on CONFIRMED docs.
        rn_raw = frappe.form_dict.get("rownames")
        rn_list = []
        if rn_raw:
            for rn in rn_raw.split(","):
                rv = rn.strip()
                if rv and rv not in rn_list:
                    rn_list.append(rv)
        if not rn_list:
            out["error"] = "rownames is required (CSV)"
        else:
            fixed = []
            errors = []
            parents = {}
            for rn in rn_list[:300]:
                row = frappe.db.get_value("Work Actuals Employee", rn,
                    ["name", "parent", "employee", "employee_name", "work_date",
                     "actual_quantity", "amount", "paid"], as_dict=True)
                if not row:
                    errors.append({"rowname": rn, "error": "not found"})
                    continue
                if frappe.utils.cint(row.paid):
                    errors.append({"rowname": rn, "error": "already paid"})
                    continue
                if frappe.utils.flt(row.amount) > 0.001:
                    errors.append({"rowname": rn, "error": "already valued"})
                    continue
                pinfo = frappe.db.get_value("Work Management Actuals", row.parent,
                    ["workflow_state", "rate"], as_dict=True)
                if not pinfo or pinfo.workflow_state != "CONFIRMED" or frappe.utils.flt(pinfo.rate) <= 0:
                    errors.append({"rowname": rn, "error": "doc not CONFIRMED or has no rate"})
                    continue
                etype = frappe.db.get_value("Employee", row.employee, "employment_type")
                if etype != "Task Worker":
                    errors.append({"rowname": rn, "error": "worker is not a Task Worker (" + str(etype) + ")"})
                    continue
                new_amt = round(frappe.utils.flt(row.actual_quantity) * frappe.utils.flt(pinfo.rate), 2)
                frappe.db.set_value("Work Actuals Employee", rn, "employment_type", "Task Worker", update_modified=False)
                frappe.db.set_value("Work Actuals Employee", rn, "count_in_payroll", 1, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", rn, "amount", new_amt, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", rn, "custom_reviewed", 0, update_modified=False)
                fixed.append({"rowname": rn, "employee": row.employee,
                              "employee_name": row.employee_name,
                              "wdate": str(row.work_date), "amount": new_amt})
                pl = parents.get(row.parent)
                if pl is None:
                    pl = []
                    parents[row.parent] = pl
                pl.append((row.employee_name or row.employee) + " " + str(row.work_date) + " → " + str(round(new_amt, 2)))
            # re-sum every touched parent
            for pname in parents:
                tots = frappe.db.sql("""
                    SELECT COALESCE(SUM(actual_quantity),0) q, COALESCE(SUM(amount),0) p,
                           COALESCE(SUM(CASE WHEN IFNULL(count_in_payroll,0)=1 THEN actual_quantity ELSE 0 END),0) twq,
                           COALESCE(SUM(CASE WHEN IFNULL(count_in_payroll,0)=0 THEN actual_quantity ELSE 0 END),0) slq,
                           COUNT(DISTINCT CASE WHEN IFNULL(count_in_payroll,0)=1 THEN employee END) pp
                    FROM `tabWork Actuals Employee` WHERE parent=%s
                """, (pname,), as_dict=True)
                if tots:
                    frappe.db.set_value("Work Management Actuals", pname, "total_actual_qty", frappe.utils.flt(tots[0].q), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "total_payment", frappe.utils.flt(tots[0].p), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "custom_tw_qty", frappe.utils.flt(tots[0].twq), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "custom_salaried_qty", frappe.utils.flt(tots[0].slq), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "payroll_people", frappe.utils.cint(tots[0].pp), update_modified=False)
            frappe.db.commit()
            for pname in parents:
                try:
                    frappe.get_doc("Work Management Actuals", pname).add_comment("Edited",
                        "Zero-pay repair by " + frappe.session.user + ": revalued at doc rate — " + "; ".join(parents[pname]))
                except Exception:
                    pass
            out["fixed"] = fixed
            out["fixed_count"] = len(fixed)
            out["fixed_total"] = sum(x["amount"] for x in fixed)
            out["errors"] = errors

    elif action == "pay_recalc_wages":
        # WAGE-DRIFT REPAIR: many plan rates were rounded to 2dp (e.g. 340/150 =
        # 2.2667 stored as 2.27), so a full day pays 340.50 / 339.96 / 342 instead
        # of the intended 340. For every plan whose implied daily wage
        # (rate x daily_target) is within 1% of 340 but not exactly 340, revalue
        # UNPAID confirmed payroll rows to qty x (340 / daily_target).
        # dry_run=1 reports what would change without touching anything.
        # Chunked (max 800 rows per call) — repeat until remaining = 0.
        recalc_dry = frappe.utils.cint(frappe.form_dict.get("dry_run"))
        WAGE = 340.0
        BAND = 3.4
        bad_plans = {}
        for r in frappe.db.sql("""
            SELECT name, rate, daily_target FROM `tabWork Management Planner`
            WHERE IFNULL(rate,0) > 0 AND IFNULL(daily_target,0) > 0
        """, as_dict=True):
            dw = frappe.utils.flt(r.rate) * frappe.utils.flt(r.daily_target)
            if abs(dw - WAGE) <= BAND and abs(dw - WAGE) > 0.001:
                bad_plans[r.name] = frappe.utils.flt(r.daily_target)
        rows_bad = []
        if bad_plans:
            rows_bad = frappe.db.sql("""
                SELECT we.name rowname, we.parent, we.employee, we.actual_quantity qty,
                       we.amount, a2.planner_request plan
                FROM `tabWork Actuals Employee` we
                INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
                INNER JOIN `tabWork Management Assigner` a2 ON ac.assignment = a2.name
                WHERE ac.workflow_state = 'CONFIRMED'
                  AND IFNULL(we.paid,0) = 0 AND IFNULL(we.count_in_payroll,0) = 1
                  AND we.actual_quantity > 0
                  AND a2.planner_request IN %s
            """, (tuple(bad_plans.keys()),), as_dict=True)
        todo = []
        old_total = 0
        new_total = 0
        for r in rows_bad:
            tgt = bad_plans.get(r.plan)
            if not tgt:
                continue
            new_amt = round(frappe.utils.flt(r.qty) * (WAGE / tgt), 2)
            if abs(new_amt - frappe.utils.flt(r.amount)) > 0.01:
                todo.append((r.rowname, r.parent, new_amt, frappe.utils.flt(r.amount)))
                old_total = old_total + frappe.utils.flt(r.amount)
                new_total = new_total + new_amt
        out["plans_affected"] = len(bad_plans)
        out["rows_to_fix"] = len(todo)
        out["old_total"] = old_total
        out["new_total"] = new_total
        out["delta"] = new_total - old_total
        if not recalc_dry and todo:
            batch = todo[:800]
            parents_r = {}
            for (rn, par, namt, oamt) in batch:
                frappe.db.set_value("Work Actuals Employee", rn, "amount", namt, update_modified=False)
                parents_r[par] = 1
            for pname in parents_r:
                tots = frappe.db.sql("""
                    SELECT COALESCE(SUM(actual_quantity),0) q, COALESCE(SUM(amount),0) p
                    FROM `tabWork Actuals Employee` WHERE parent=%s
                """, (pname,), as_dict=True)
                if tots:
                    frappe.db.set_value("Work Management Actuals", pname, "total_payment", frappe.utils.flt(tots[0].p), update_modified=False)
            frappe.db.commit()
            out["fixed_now"] = len(batch)
            out["parents_resummed"] = len(parents_r)
            out["remaining"] = len(todo) - len(batch)

    elif action == "pay_round_amounts":
        # HYGIENE: round unpaid confirmed row amounts to the cent (removes float
        # artifacts like 338.99999999999994) and re-sum the parents. Chunked.
        rr_rows = frappe.db.sql("""
            SELECT we.name rowname, we.parent, we.amount
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE ac.workflow_state = 'CONFIRMED' AND IFNULL(we.paid,0) = 0
              AND we.amount != ROUND(we.amount, 2)
            LIMIT 900
        """, as_dict=True)
        parents_rr = {}
        for r in rr_rows:
            frappe.db.set_value("Work Actuals Employee", r.rowname, "amount", round(frappe.utils.flt(r.amount), 2), update_modified=False)
            parents_rr[r.parent] = 1
        for pname in parents_rr:
            tots = frappe.db.sql("""
                SELECT COALESCE(SUM(amount),0) p FROM `tabWork Actuals Employee` WHERE parent=%s
            """, (pname,), as_dict=True)
            if tots:
                frappe.db.set_value("Work Management Actuals", pname, "total_payment", round(frappe.utils.flt(tots[0].p), 2), update_modified=False)
        frappe.db.commit()
        remaining_rr = frappe.db.sql("""
            SELECT COUNT(*) n FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE ac.workflow_state = 'CONFIRMED' AND IFNULL(we.paid,0) = 0
              AND we.amount != ROUND(we.amount, 2)
        """, as_dict=True)
        out["rounded"] = len(rr_rows)
        out["parents_resummed"] = len(parents_rr)
        out["remaining"] = frappe.utils.cint(remaining_rr[0].n) if remaining_rr else 0

    elif action == "pay_fix_duplicates":
        # DUPLICATE-DAY REPAIR: for every (worker, task, date) recorded in more
        # than one confirmed document, KEEP the copy in the earliest-created
        # document and zero the rest (qty and amount, review stamps reset).
        # Groups containing a paid row are skipped — those need manual handling.
        # Chunked (max 150 groups per call); dry_run=1 only reports.
        fd_dry = frappe.utils.cint(frappe.form_dict.get("dry_run"))
        fd_from = frappe.form_dict.get("from_date") or "2000-01-01"
        fd_to = frappe.form_dict.get("to_date") or str(frappe.utils.today())
        fd_farm = (frappe.form_dict.get("farms") or "").strip()
        fdconds = "ac.workflow_state='CONFIRMED' AND we.actual_quantity > 0 AND we.work_date BETWEEN %s AND %s"
        fdparams = [fd_from, fd_to]
        fd_flist = []
        if fd_farm:
            for f in fd_farm.split(","):
                fv = f.strip()
                if fv:
                    fd_flist.append(fv)
        if fd_flist:
            fdconds = fdconds + " AND TRIM(ac.farm) IN %s"
            fdparams.append(tuple(fd_flist))
        fd_rows = frappe.db.sql("""
            SELECT we.name rowname, we.parent, we.employee, we.employee_name,
                   ac.task, we.work_date wdate, we.actual_quantity qty, we.amount,
                   IFNULL(we.paid,0) paid, ac.creation doc_created
            FROM `tabWork Actuals Employee` we
            INNER JOIN `tabWork Management Actuals` ac ON we.parent = ac.name
            WHERE """ + fdconds + """
            ORDER BY we.employee, ac.task, we.work_date, ac.creation
        """, tuple(fdparams), as_dict=True)
        groups = {}
        for r in fd_rows:
            k = (r.employee, r.task or "", str(r.wdate))
            g = groups.get(k)
            if g is None:
                g = []
                groups[k] = g
            g.append(r)
        dup_groups = []
        skipped_paid = 0
        for k in groups:
            g = groups[k]
            if len(g) < 2:
                continue
            if any(frappe.utils.cint(x.paid) for x in g):
                skipped_paid = skipped_paid + 1
                continue
            dup_groups.append(g)
        out["dup_groups"] = len(dup_groups)
        out["skipped_paid_groups"] = skipped_paid
        excess = 0
        zero_rows = 0
        for g in dup_groups:
            for x in g[1:]:
                excess = excess + frappe.utils.flt(x.amount)
                zero_rows = zero_rows + 1
        out["rows_to_zero"] = zero_rows
        out["excess_total"] = excess
        if not fd_dry and dup_groups:
            batch = dup_groups[:150]
            parents_fd = {}
            for g in batch:
                keep = g[0]
                for x in g[1:]:
                    frappe.db.set_value("Work Actuals Employee", x.rowname, "actual_quantity", 0, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", x.rowname, "amount", 0, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", x.rowname, "custom_reviewed", 0, update_modified=False)
                    pl = parents_fd.get(x.parent)
                    if pl is None:
                        pl = []
                        parents_fd[x.parent] = pl
                    pl.append((x.employee_name or x.employee) + " " + str(x.wdate) + " (" + str(x.task) + ", kept in " + keep.parent + ")")
            for pname in parents_fd:
                tots = frappe.db.sql("""
                    SELECT COALESCE(SUM(actual_quantity),0) q, COALESCE(SUM(amount),0) p,
                           COALESCE(SUM(CASE WHEN IFNULL(count_in_payroll,0)=1 THEN actual_quantity ELSE 0 END),0) twq,
                           COALESCE(SUM(CASE WHEN IFNULL(count_in_payroll,0)=0 THEN actual_quantity ELSE 0 END),0) slq,
                           COUNT(DISTINCT CASE WHEN IFNULL(count_in_payroll,0)=1 AND actual_quantity > 0 THEN employee END) pp
                    FROM `tabWork Actuals Employee` WHERE parent=%s
                """, (pname,), as_dict=True)
                if tots:
                    frappe.db.set_value("Work Management Actuals", pname, "total_actual_qty", frappe.utils.flt(tots[0].q), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "total_payment", round(frappe.utils.flt(tots[0].p), 2), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "custom_tw_qty", frappe.utils.flt(tots[0].twq), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "custom_salaried_qty", frappe.utils.flt(tots[0].slq), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "payroll_people", frappe.utils.cint(tots[0].pp), update_modified=False)
            frappe.db.commit()
            for pname in parents_fd:
                try:
                    frappe.get_doc("Work Management Actuals", pname).add_comment("Edited",
                        "Duplicate-day repair by " + frappe.session.user + ": zeroed re-entered day(s) — " + "; ".join(parents_fd[pname][:12]))
                except Exception:
                    pass
            out["fixed_groups"] = len(batch)
            out["remaining_groups"] = len(dup_groups) - len(batch)

    elif action == "pay_bulk_withdraw":
        # Return SEVERAL pending payments to Unpaid in one go — same as
        # pay_run_withdraw per entry: clear refs + review stamps, delete the doc.
        nm_raw = frappe.form_dict.get("names")
        nm_list = []
        if nm_raw:
            for nm in nm_raw.split(","):
                nv = nm.strip()
                if nv and nv not in nm_list:
                    nm_list.append(nv)
        if not nm_list:
            out["error"] = "names is required (CSV)"
        else:
            results = []
            done_n = 0
            rows_n = 0
            for nm in nm_list[:200]:
                cur = frappe.db.get_value("Work Management Payment", nm, "workflow_state")
                if not cur:
                    results.append({"name": nm, "error": "not found"})
                    continue
                if cur != "Unpaid":
                    results.append({"name": nm, "error": "state is " + str(cur)})
                    continue
                if frappe.db.sql("""
                    SELECT sd.parent FROM `tabSalary Detail` sd
                    INNER JOIN `tabAdditional Salary` a ON a.name = sd.additional_salary
                    WHERE a.ref_doctype = 'Work Management Payment' AND a.ref_docname = %(n)s LIMIT 1
                """, {"n": nm}, as_dict=True):
                    results.append({"name": nm, "error": "a Salary Slip has already paid this through payroll"})
                    continue
                for asr in frappe.db.sql("""
                    SELECT name FROM `tabAdditional Salary`
                    WHERE ref_doctype = 'Work Management Payment' AND ref_docname = %(n)s
                      AND docstatus = 1
                """, {"n": nm}, as_dict=True):
                    adoc = frappe.get_doc("Additional Salary", asr.name)
                    adoc.flags.ignore_permissions = True
                    adoc.cancel()
                rws = frappe.db.get_all("Work Actuals Employee",
                    filters={"payment_ref": nm, "paid": 0}, pluck="name")
                for rn in rws:
                    frappe.db.set_value("Work Actuals Employee", rn, "payment_ref", None, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", rn, "custom_reviewed", 0, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", rn, "custom_reviewed_by", None, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", rn, "custom_reviewed_at", None, update_modified=False)
                wt = frappe.db.get_value("Work Management Payment", nm, "run_title")
                try:
                    frappe.delete_doc("Work Management Payment", nm, ignore_permissions=True, force=True)
                    # commit per document: a lock clash on one entry must not roll
                    # back the entries already returned, which is what made the bulk
                    # action look like it had done nothing
                    frappe.db.commit()
                except Exception as e:
                    frappe.db.rollback()
                    results.append({"name": nm, "error": str(e)[:120]})
                    continue
                done_n = done_n + 1
                rows_n = rows_n + len(rws)
                results.append({"name": nm, "run_title": wt, "rows_reset": len(rws)})
            frappe.db.commit()
            out["results"] = results
            out["withdrawn"] = done_n
            out["rows_reset"] = rows_n
            out["errors"] = len([r for r in results if r.get("error")])

    elif action == "pay_purge_queue":
        # Empty the accounts queue wholesale. Same end state as returning every
        # entry to unpaid -- refs and review stamps cleared, documents deleted --
        # but in one server-side pass rather than a round trip per document.
        # Refuses anything payroll has already consumed. Chunked: repeat until
        # "remaining" comes back 0.
        pq_chunk = frappe.utils.cint(frappe.form_dict.get("chunk") or 400)
        if pq_chunk < 1 or pq_chunk > 1000:
            pq_chunk = 400
        pq_total = frappe.db.count("Work Management Payment", {"workflow_state": "Unpaid"})
        pq_rows = frappe.db.sql("""
            SELECT name FROM `tabWork Management Payment`
            WHERE workflow_state = 'Unpaid' ORDER BY creation LIMIT %(n)s
        """, {"n": pq_chunk}, as_dict=True)
        pq_names = [r.name for r in pq_rows]
        out["total"] = pq_total
        out["batch"] = len(pq_names)
        if not pq_names:
            out["remaining"] = 0
            out["deleted"] = 0
        else:
            pq_used = {}
            for u in frappe.db.sql("""
                SELECT a.ref_docname n FROM `tabSalary Detail` sd
                INNER JOIN `tabAdditional Salary` a ON a.name = sd.additional_salary
                WHERE a.ref_doctype = 'Work Management Payment' AND a.ref_docname IN %(p)s
            """, {"p": tuple(pq_names)}, as_dict=True):
                pq_used[u.n] = 1
            pq_go = [n for n in pq_names if not pq_used.get(n)]
            pq_freed = 0
            if pq_go:
                for rr in frappe.db.sql("""
                    SELECT name FROM `tabWork Actuals Employee`
                    WHERE payment_ref IN %(p)s AND IFNULL(paid,0) = 0
                """, {"p": tuple(pq_go)}, as_dict=True):
                    frappe.db.set_value("Work Actuals Employee", rr.name, "payment_ref", None, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", rr.name, "custom_reviewed", 0, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", rr.name, "custom_reviewed_by", None, update_modified=False)
                    frappe.db.set_value("Work Actuals Employee", rr.name, "custom_reviewed_at", None, update_modified=False)
                    pq_freed = pq_freed + 1
                frappe.db.commit()
            pq_gone = 0
            for n in pq_go:
                for asr in frappe.db.sql("""
                    SELECT name FROM `tabAdditional Salary`
                    WHERE ref_doctype = 'Work Management Payment' AND ref_docname = %(n)s
                      AND docstatus = 1
                """, {"n": n}, as_dict=True):
                    adoc = frappe.get_doc("Additional Salary", asr.name)
                    adoc.flags.ignore_permissions = True
                    adoc.cancel()
                frappe.delete_doc("Work Management Payment", n, ignore_permissions=True, force=True)
                pq_gone = pq_gone + 1
            frappe.db.commit()
            out["deleted"] = pq_gone
            out["rows_freed"] = pq_freed
            out["skipped_paid_by_payroll"] = len(pq_used)
            out["remaining"] = frappe.db.count("Work Management Payment", {"workflow_state": "Unpaid"})

    elif action == "pay_fix_orphan_refs":
        # REPAIR: a work row keeps its payment_ref long after the payment it names
        # has gone. pay_purge_queue clears the refs of the documents it deletes,
        # but a payment removed any other way -- straight off the list view, say --
        # leaves its rows stamped. Those rows are then invisible to every send,
        # because pay_worker_submit only picks up rows whose payment_ref is empty,
        # so the worker looks payable on screen and refuses to send.
        # Only rows that are NOT paid and whose ref names a payment that no longer
        # exists are cleared. dry_run=1 reports without writing.
        fo_dry = frappe.utils.cint(frappe.form_dict.get("dry_run") or 0)
        fo_chunk = frappe.utils.cint(frappe.form_dict.get("chunk") or 500)
        if fo_chunk < 1 or fo_chunk > 2000:
            fo_chunk = 500
        fo_rows = frappe.db.sql("""
            SELECT we.name, we.employee, we.payment_ref, we.amount
            FROM `tabWork Actuals Employee` we
            LEFT JOIN `tabWork Management Payment` p ON p.name = we.payment_ref
            WHERE IFNULL(we.payment_ref,'') != ''
              AND IFNULL(we.paid,0) = 0
              AND p.name IS NULL
            ORDER BY we.name
            LIMIT %(n)s
        """, {"n": fo_chunk}, as_dict=True)
        fo_total = frappe.db.sql("""
            SELECT COUNT(*) n, COALESCE(SUM(we.amount),0) a
            FROM `tabWork Actuals Employee` we
            LEFT JOIN `tabWork Management Payment` p ON p.name = we.payment_ref
            WHERE IFNULL(we.payment_ref,'') != ''
              AND IFNULL(we.paid,0) = 0
              AND p.name IS NULL
        """, as_dict=True)[0]
        out["dry_run"] = fo_dry
        out["orphan_rows"] = frappe.utils.cint(fo_total.n)
        out["orphan_amount"] = frappe.utils.flt(fo_total.a)
        out["batch"] = len(fo_rows)
        out["sample"] = [{"row": r.name, "employee": r.employee, "ref": r.payment_ref} for r in fo_rows[:8]]
        fo_done = 0
        if not fo_dry:
            for r in fo_rows:
                frappe.db.set_value("Work Actuals Employee", r.name, "payment_ref", None, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", r.name, "custom_reviewed", 0, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", r.name, "custom_reviewed_by", None, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", r.name, "custom_reviewed_at", None, update_modified=False)
                fo_done = fo_done + 1
            frappe.db.commit()
        out["cleared"] = fo_done
        out["remaining"] = frappe.utils.cint(frappe.db.sql("""
            SELECT COUNT(*) n FROM `tabWork Actuals Employee` we
            LEFT JOIN `tabWork Management Payment` p ON p.name = we.payment_ref
            WHERE IFNULL(we.payment_ref,'') != ''
              AND IFNULL(we.paid,0) = 0
              AND p.name IS NULL
        """, as_dict=True)[0].n)

    elif action == "pay_release_inactive":
        # CLEAN SLATE for the "left the company but still assigned" backlog:
        # mark every Active assignment row of a non-Active employee as Left
        # (dated today), recount the assignments and leave comments. The
        # auto-release checkbox only covers FUTURE deactivations — this handles
        # the existing rows. Chunked (150 rows/call); dry_run=1 reports only.
        ri_dry = frappe.utils.cint(frappe.form_dict.get("dry_run"))
        ri_farm = (frappe.form_dict.get("farms") or "").strip()
        riconds = ""
        riparams = []
        ri_flist = []
        if ri_farm:
            for f in ri_farm.split(","):
                fv = f.strip()
                if fv:
                    ri_flist.append(fv)
        if ri_flist:
            riconds = " AND TRIM(a.farm) IN %s"
            riparams.append(tuple(ri_flist))
        ri_rows = frappe.db.sql("""
            SELECT we.name rowname, we.employee, we.employee_name, a.name asg, a.farm
            FROM `tabWork Assignment Employee` we
            INNER JOIN `tabWork Management Assigner` a ON we.parent = a.name
            INNER JOIN `tabEmployee` emp ON emp.name = we.employee
            WHERE a.workflow_state IN ('Pending Farm Manager','Pending HR Head','Pending GM','Assigned')
              AND IFNULL(we.status,'Active') = 'Active'
              AND emp.status != 'Active'
              """ + riconds + """
            ORDER BY a.name LIMIT 2000
        """, tuple(riparams), as_dict=True)
        wset_ri = {}
        for r in ri_rows:
            wset_ri[r.employee] = 1
        out["rows_found"] = len(ri_rows)
        out["workers_found"] = len(wset_ri)
        if not ri_dry and ri_rows:
            batch = ri_rows[:150]
            touched = {}
            for r in batch:
                frappe.db.set_value("Work Assignment Employee", r.rowname, "status", "Left", update_modified=False)
                frappe.db.set_value("Work Assignment Employee", r.rowname, "left_date", frappe.utils.today(), update_modified=False)
                pl = touched.get(r.asg)
                if pl is None:
                    pl = []
                    touched[r.asg] = pl
                pl.append(r.employee_name or r.employee)
            for asg in touched:
                cnt = frappe.db.sql("""
                    SELECT COUNT(*) n FROM `tabWork Assignment Employee`
                    WHERE parent = %s AND IFNULL(status,'Active') = 'Active'
                """, (asg,), as_dict=True)
                if cnt:
                    frappe.db.set_value("Work Management Assigner", asg, "assigned_count", frappe.utils.cint(cnt[0].n), update_modified=False)
            frappe.db.commit()
            for asg in touched:
                try:
                    frappe.get_doc("Work Management Assigner", asg).add_comment("Comment",
                        "Released (clean slate) by " + frappe.session.user + " — deactivated in HR: " + ", ".join(touched[asg][:15]))
                except Exception:
                    pass
            out["released_now"] = len(batch)
            out["assignments_touched"] = len(touched)
            out["remaining"] = len(ri_rows) - len(batch)

    elif action == "pay_worker_edit_days":
        # BULK audit correction: change several worker-day quantities in one save.
        # Same rules per row as pay_worker_edit_day; parents re-sum once, one
        # audit comment per document lists every change.
        emp = frappe.form_dict.get("employee")
        rows_raw = frappe.form_dict.get("rows")
        if not emp or not rows_raw:
            out["error"] = "employee and rows are required"
        else:
            changes = []
            for c in rows_raw.split("|"):
                bits = c.split("~")
                if len(bits) >= 2 and bits[0]:
                    changes.append((bits[0], frappe.utils.flt(bits[1])))
            updated = []
            errors = []
            parents_e = {}
            for (rowname, new_qty) in changes[:300]:
                if new_qty < 0:
                    errors.append({"rowname": rowname, "error": "negative qty"})
                    continue
                row = frappe.db.get_value("Work Actuals Employee", rowname,
                    ["name", "parent", "employee", "employee_name", "work_date",
                     "actual_quantity", "amount", "paid", "count_in_payroll", "payment_ref"], as_dict=True)
                if not row or row.employee != emp:
                    errors.append({"rowname": rowname, "error": "not this worker's row"})
                    continue
                if frappe.utils.cint(row.paid):
                    errors.append({"rowname": rowname, "error": "already paid"})
                    continue
                if not frappe.utils.cint(row.count_in_payroll):
                    errors.append({"rowname": rowname, "error": "not payroll-counted"})
                    continue
                if row.payment_ref and frappe.db.get_value("Work Management Payment", row.payment_ref, "workflow_state") == "Unpaid":
                    errors.append({"rowname": rowname, "error": "inside " + row.payment_ref + " — return it to unpaid first"})
                    continue
                pstate = frappe.db.get_value("Work Management Actuals", row.parent, "workflow_state")
                if pstate != "CONFIRMED":
                    errors.append({"rowname": rowname, "error": "doc not CONFIRMED"})
                    continue
                old_qty = frappe.utils.flt(row.actual_quantity)
                old_amt = frappe.utils.flt(row.amount)
                if abs(old_qty - new_qty) < 0.0001:
                    continue
                rate = (old_amt / old_qty) if old_qty else frappe.utils.flt(
                    frappe.db.get_value("Work Management Actuals", row.parent, "rate"))
                new_amt = round(new_qty * rate, 2)
                frappe.db.set_value("Work Actuals Employee", rowname, "actual_quantity", new_qty, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", rowname, "amount", new_amt, update_modified=False)
                frappe.db.set_value("Work Actuals Employee", rowname, "custom_reviewed", 0, update_modified=False)
                pl = parents_e.get(row.parent)
                if pl is None:
                    pl = []
                    parents_e[row.parent] = pl
                pl.append((row.employee_name or emp) + " " + str(row.work_date) + ": qty " + str(old_qty) + " → " + str(new_qty) + ", pay " + str(round(old_amt, 2)) + " → " + str(new_amt))
                updated.append({"rowname": rowname, "qty": new_qty, "amount": new_amt})
            for pname in parents_e:
                tots = frappe.db.sql("""
                    SELECT COALESCE(SUM(actual_quantity),0) q, COALESCE(SUM(amount),0) p
                    FROM `tabWork Actuals Employee` WHERE parent=%s
                """, (pname,), as_dict=True)
                if tots:
                    frappe.db.set_value("Work Management Actuals", pname, "total_actual_qty", frappe.utils.flt(tots[0].q), update_modified=False)
                    frappe.db.set_value("Work Management Actuals", pname, "total_payment", round(frappe.utils.flt(tots[0].p), 2), update_modified=False)
            frappe.db.commit()
            for pname in parents_e:
                try:
                    frappe.get_doc("Work Management Actuals", pname).add_comment("Edited",
                        "Bulk audit correction by " + frappe.session.user + ": " + "; ".join(parents_e[pname][:12]))
                except Exception:
                    pass
            out["updated"] = len(updated)
            out["errors"] = errors
            out["parents"] = len(parents_e)

    # ===== DASHBOARD (fast: grouped queries) =====
    else:
        out["error"] = "unknown action: " + str(action)

    return out
